pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let horizon = (remaining / total_items.max(1) as f64).min(1.0);
    let mut score = post_f;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits: reward tight two-item packing with lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 12.0;
            }
            if leftover_after_next >= 3 * next_item_size {
                score -= 4.0;
                if remaining > 96.0 {
                    score -= 4.0;
                }
            }
        }
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0;
        }
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        if post_residual % 25 == 0 {
            score -= 7.0;
        } else if post_residual % 20 == 0 {
            score -= 5.0;
        }
        if remaining > 48.0 && leftover_after_next >= next_item_size {
            let two_post = leftover_after_next - next_item_size;
            if two_post >= item_size {
                score -= 3.5;
            }
            if two_post == 0 {
                score -= 12.0;
            }
        }
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // graded reuse reward — sharper cliff near exact reuse, scaled by horizon
        if leftover_after_next > 0 && leftover_after_next < next_item_size {
            score += 2.5 * (leftover_after_next as f64 / next_item_size as f64) * (0.5 + horizon);
        }
        // deep chained reuse reward, stronger late in stream
        if post_residual >= 2 * next_item_size + item_size && remaining > 24.0 {
            score -= 10.0 * horizon;
        }
        // reward residuals aligned to common item sizes when stream is long
        if remaining > 64.0 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 3.5;
        }
        // GEN42: multi-step lookahead — reward residuals hosting next item twice/thrice
        if post_residual >= 2 * next_item_size && remaining > 32.0 {
            let two_slack = post_residual - 2 * next_item_size;
            if two_slack == 0 {
                score -= 10.0 * (0.5 + horizon);
            } else if two_slack <= 6 {
                score -= 4.5 * (0.5 + horizon);
            }
        }
        if post_residual >= 3 * next_item_size && remaining > 96.0 {
            score -= 5.0 * horizon;
        }
        // GEN42: extended slack shaping with exact-zero bonus
        if leftover_after_next == 0 {
            score -= 16.0;
        } else if leftover_after_next <= 6 {
            score -= 9.0 * (7.0 - leftover_after_next as f64) * (0.5 + horizon);
        }
    }
    // Next item will NOT fit: penalize dead space, worse when small.
    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
        if post_residual > 0 && gap <= 6 {
            score += 6.0;
        }
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
            if remaining > 64.0 && post_residual >= 8 {
                score += 0.4 * (gap as f64).min(20.0);
            }
            // barely-too-small residuals are the main dead-space source
            if gap <= 6 && post_residual >= item_size {
                score += (7.0 - gap as f64) * 2.2 * (0.4 + horizon);
            }
            // fragmentation-scaled compounding penalty
            let frag = (open_bins_count as f64 / 16.0).min(1.0);
            if remaining > 32.0 {
                score += 1.3 * gap as f64 * frag * (remaining / 512.0).min(1.0);
            }
            // GEN42: dead_frac-scaled penalty with horizon
            let dead_frac = gap as f64 / next_item_size as f64;
            score += 2.5 * dead_frac * horizon * (1.0 + post_f / cap_f);
        }
        // GEN42: near-miss residuals penalized harder
        if post_residual > 0 && post_residual >= item_size {
            let miss = gap as f64;
            if miss <= 10.0 {
                score += (10.5 - miss) * 2.4 * (0.4 + horizon);
            }
        }
    }

    score -= (mean_residual - post_f) * 0.5;

    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    score += 32.0 * (post_f / cap_f) * (post_f / cap_f);

    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - post_f / cap_f);
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - post_f / cap_f);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            if post_f <= 0.10 * cap_f && remaining > 220.0 {
                score -= 12.0;
            }
            if remaining > 96.0 && (next_item_size as f64) > 3.0 * post_f {
                score -= 10.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        let next_frac = next_item_size as f64 / cap_f;
        if next_frac > 0.5 && remaining > 64.0 {
            score -= 14.0 * (next_frac - 0.5);
        }
        // fresh bin preserves contiguous space for a large next item
        if next_frac > 0.5 && fitting_bins_count <= 2 && remaining > 32.0 {
            score -= 10.0 * next_frac;
        }
        if next_frac < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        if open_bins_count > 8 && remaining > 128.0 && next_frac < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_frac);
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
        if remaining < 32.0 {
            score += 0.6 * (32.0 - remaining);
        }
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        if remaining < 12.0 {
            score += 55.0;
        }
        // fresh-bin utility gate based on expected future demand
        let expected_future = remaining * (mean_residual / cap_f).max(0.15);
        if expected_future < 0.5 * cap_f && open_bins_count > 3 {
            score += 7.0 * (1.0 - expected_future / (0.5 * cap_f));
        }
        if next_item_size as f64 > 0.6 * cap_f && open_bins_count > 6 && remaining > 200.0 {
            score -= 8.0;
        }
        // GEN42: fresh-bin pull when fragmentation is high and next item medium
        if open_bins_count > 10 && next_frac > 0.35 && remaining > 96.0 && next_item_size > post_residual {
            score -= 5.0;
        }
        // GEN42: discourage opening fresh bin when an open bin achieves exact fit with next item
        if next_item_size > 0 && post_residual == next_item_size && remaining > 16.0 {
            score += 45.0;
        }
        // GEN42: fresh bin for very large next item late in stream
        if next_item_size as f64 > 0.85 * cap_f && remaining > 96.0 {
            score -= 6.0;
        }
    } else {
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
            score += 5.0;
        }
        if fitting_bins_count > 3 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            let curvature = 0.08 + 0.04 * (1.0 - horizon);
            score += curvature * (next_post as f64 - next_item_size as f64).abs();
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score += 0.05 * (post_f * post_f) / cap_f;
        }
        // residual-reusability shaping in existing bins
        if next_item_size > 0 && post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 4 {
                score -= 7.5 * (5.0 - slack as f64) * (0.5 + horizon);
            }
        }
        // GEN42: small-residual class bonus to reduce dead space in nearly-full bins
        if post_residual < 8 {
            score -= 35.0;
        } else if post_residual < 12 {
            score += 45.0 * (12 - post_residual) as f64;
        } else if post_residual <= 20 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let mut score = post_f;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the leftover: reward tight two-item packing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        // chain lookahead: same item could fit again after the next one
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 12.0;
            }
            // three-step chain potential
            if leftover_after_next >= 3 * next_item_size {
                score -= 4.0;
            }
            // two-step exact chain (borrowed from best): leftover after two nexts
            let two_post = leftover_after_next - next_item_size;
            if two_post == 0 {
                score -= 30.0;
            } else if two_post <= 6 {
                score -= 14.0;
            } else if two_post >= next_item_size {
                score -= 6.0;
            }
        }
        // exact fill after next item is highly desirable
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0;
        }
        // dead-space: leftover after next is unusably small for next item
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // bonus when residual is a multiple of the next item (perfect tiling)
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
        // reward residuals that are friendly multiples (from best heuristic)
        if post_residual % 25 == 0 {
            score -= 7.0;
        }
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
    }
    // Next item will NOT fit: penalize dead space, worse when it's small.
    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
        if post_residual > 0 && gap <= 6 {
            score += 6.0; // barely-too-small residual is wasted potential
        }
        // strong dead-space penalty scaled by residual fraction
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
        }
        // extra graded penalty for stranded residuals just below next item
        if post_residual >= 8 && post_residual < next_item_size {
            score += 0.4 * gap as f64;
        }
    }

    // Reward bins tighter than the mean residual (good fill), punish loose ones.
    score -= (mean_residual - post_f) * 0.5;

    // Reward tightness of the actual placement relative to bin residual.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Quadratic residual fraction: strong pull toward full bins.
    score += 32.0 * (post_f / cap_f) * (post_f / cap_f);

    // Last-chance bin: use it when the fit is tight.
    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - post_f / cap_f);
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving tiny unusable fragments (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    // Progress term: keep flexibility early, prefer closing bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    // NEW-BIN CANDIDATE handling: default unattractive; open only when open
    // bins cannot absorb the item well and stream is long enough to matter.
    if bin_residual == bin_capacity {
        let remaining = (total_items - step_index) as f64;
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        // fresh-bin lookahead: open a new bin when remaining stream is long
        // and the only fits would strand residuals smaller than the next item
        if next_item_size > post_residual {
            if post_residual < next_item_size && remaining > 48.0 {
                score -= 30.0 * (1.0 - post_f / cap_f);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            // best-heuristic idea: fresh bin sized for the next item is very good
            if next_item_size as f64 > post_f && next_item_size <= bin_residual {
                score -= 90.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64); // penalize large dead space quadratically
        // Penalize residuals that are too small to fit the smallest plausible item
        if pr < 10.0 {
            score += 50.0;
        }
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            score -= 60.0;
        } else {
            score += 40.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 300.0;
    } else if fitting_bins_count > 1 {
        score += 10.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer filling bins that are already low-residual relative to the mean.
    score += (bin_residual as f64 - mean_residual) * 0.8;

    // Mild preference for reusing existing bins vs opening new ones, growing with stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity as f64 - item_size as f64);
        score = 150.0 + waste * 0.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 80.0; // new bin also fits next item
        }
        if fitting_bins_count == 1 {
            score += 200.0; // a real bin exists that fits; avoid opening new
        }
    }

    // Slight preference to keep number of open bins from exploding early.
    score += (open_bins_count as f64) * 0.3 * (1.0 - progress);

    score
}

