        // smooth discount for reusable remainders after the next item
        score -= 5.0 * ((leftover_after_next as f64) / (next_item_size as f64)).min(2.0) * horizon;
        // small clean remainders are excellent staging space
        if leftover_after_next <= 3 {
            score -= 18.0 * (4 - leftover_after_next) as f64;
        } else if leftover_after_next % 10 == 0 {
            score -= 12.0;
        }
        // curvature shaping: prefer post residuals near the next item size
        let curvature = 0.08 + 0.04 * (1.0 - horizon);
        score += curvature * ((leftover_after_next as f64) - (next_item_size as f64)).abs();
        // small-residual sweet spot: residuals of 8-11 fit many small items
        if post_residual >= 8 && post_residual <= 11 {
            score -= 10.0;
        }
    }
    // Next item will NOT fit: penalize dead space, worse when it's small.
    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
        if post_residual > 0 && gap <= 6 {
            score += 6.0; // barely-too-small residual is wasted potential
        }
        // strong dead-space penalty scaled by residual fraction
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
            // stranded-space compounding penalty on long streams
            if remaining > 64.0 && post_residual >= 8 {
                score += 0.4 * (gap as f64).min(20.0);
            }
            // stranded-fraction coupling: unusable fraction of the residual
            // weighted by remaining stream; dead space late is a real loss
            let dead_frac = gap as f64 / next_item_size as f64;
            score += 2.5 * dead_frac * horizon * (1.0 + wf);
            // proportional stranded-space penalty for medium residuals
            if post_residual >= 8 {
                score += 0.06 * post_f * (remaining / 256.0).min(1.0);
            }
        }
    }

    // Reward bins tighter than the mean residual (good fill), punish loose ones.
    score -= (mean_residual - post_f) * 0.5;

    // Reward tightness of the actual placement relative to bin residual.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Quadratic residual fraction: strong pull toward full bins.
    score += 32.0 * (post_f / cap_f) * (post_f / cap_f);

    // Last-chance bin: use it when the fit is tight.
    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - post_f / cap_f);
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
