    // Penalize leaving tiny unusable fragments (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    } else if post_residual < 12 {
        score += 20.0 * (12 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    // Progress term: keep flexibility early, prefer closing bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    // NEW-BIN CANDIDATE handling: default unattractive; open only when open
    // bins cannot absorb the item well and stream is long enough to matter.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        // fresh-bin lookahead: open a new bin when remaining stream is long
        // and the only fits would strand residuals smaller than the next item
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - post_f / cap_f);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            if post_f <= 0.10 * cap_f && remaining > 220.0 {
                score -= 12.0;
            }
            if remaining > 96.0 && (next_item_size as f64) > 3.0 * post_f {
                score -= 10.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        // large next item makes a fresh full-capacity bin attractive
        let next_frac = next_item_size as f64 / cap_f;
        if next_frac > 0.5 && remaining > 64.0 {
            score -= 14.0 * (next_frac - 0.5);
        }
        // fresh-bin sizing gate: tiny next item + many open bins => fragmentation
        if next_frac < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        if open_bins_count > 8 && remaining > 128.0 && next_frac < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_frac);
        }
        // fresh-bin rescue for large incoming items with many open bins
        if open_bins_count > 6 && remaining > 200.0 && next_frac > 0.6 {
            score -= 8.0;
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
        // endgame fresh-bin tightening: consolidate before the final phase
        if remaining < 32.0 {
            score += 0.6 * (32.0 - remaining);
        }
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        if remaining < 12.0 {
            score += 55.0;
        }
    } else {
        // existing-bin refinement: penalize residual far above the next item
        // size late in the stream when it cannot be reused soon
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
            score += 5.0;
        }
        // tolerate imperfect fits less when many bins fit (keep tight bins tight)
        if fitting_bins_count > 3 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        // mild quadratic penalty for loose fits when few bins compete
        if fitting_bins_count <= 2 && post_residual > 0 {
            score += 0.05 * (post_f * post_f) / cap_f;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; anything below a "useful gap" threshold is heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fill: perfect
    } else if post_residual <= 10 {
        // small dead gap: nearly worthless leftover
        score += (12.0 - post_residual as f64) * 8.0;
    } else if post_residual <= 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = item_size as f64 / (item_size + post_residual) as f64;
    score -= tightness * 25.0;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits the post-residual, this placement
    // sets up a chain — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // extra reward if next item fills it nearly exactly
        let gap_after_next = post_residual as f64 - next_item_size as f64;
        if gap_after_next < 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        // next item can't use the tiny leftover: penalize creating it
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item is large and current bin's post-fit is poor.
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin
        score = 55.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // next item pairs well in a fresh bin
        }
    }

    // Mild preference for bins below mean residual (consolidating emptier bins)
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

