        score -= 6.0;
    }

    // Compatibility coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            // lookahead fits: strong reward, scaled by how snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.15 * slack;
        } else {
            // next item won't fit here: penalize, worse if close miss
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * miss.min(30.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins have bad fits
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * mean_residual - 0.2 * open_bins_count as f64;
        // late in stream, avoid opening new bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // new bin can host next item too
