    }

    // Modulo-10 harmonic texture on post_residual: multiples of 10 align with item grid
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Mild preference for tight fits overall
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
