pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual cost, damped by stream progress
    let mut score = pr * (1.0 + 0.5 * progress);

    // Smooth non-linear penalty for dead space: quadratic in normalized residual
    score += 20.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Cubic interaction: very tight fits are strongly rewarded, scaled by progress
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Coupling with mean residual: prefer bins below mean residual (tighter than average)
    let mean_norm = mean_residual / cap;
    score += 8.0 * (norm_pr - mean_norm).abs() * (1.0 - progress);

    // Lookahead: reward if next item can fit into post residual
    if next_item_size > 0 {
        let next_fits = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 6.0 * next_fits * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for proliferating open bins early in the stream
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize post_residuals that fall into "dead" classes: too small to fit
    // typical items (sizes 1..100), i.e. residual < 10 is pure waste.
    if post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Reward residuals in useful harmonic classes: multiples of common item sizes
    // (10, 20, 25, 50) are more likely to be exactly filled later.
    let useful = [10u32, 20, 25, 50];
    for u in useful.iter() {
        if post_residual % u == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Non-linear bonus for tight fits: exponential reward as post_residual -> 0.
    score -= 25.0 * (-frac * 8.0).exp();

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after < 10 {
            score -= 30.0; // chain of tight fits
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty scaled by gap.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin should only win when the item
    // is large relative to capacity (would leave messy small residuals elsewhere)
    // or when open bins are already crowded (mean residual low).
    if bin_residual == bin_capacity {
        let load = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for big items early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * load;
        // Late in the stream, or when many bins are open, discourage new bins.
        score += 25.0 * progress;
        score += 3.0 * open_bins_count as f64;
        // If mean residual is large, existing bins likely fit fine: penalize new bin.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer consolidating
    // (i.e. favor bins with small residuals, which the base term already does).
    score += 0.05 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are "unusable" gaps -> heavy penalty proportional to wasted capacity.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit reward: proportional fill of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
