        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement strongly (chained perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual - next_item_size < 10 {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit (residual too tight relative to item) or bins are few.
    if bin_residual == bin_capacity {
        let tight = (bin_capacity - item_size) < 10;
        let crowded = open_bins_count as f64 > mean_residual / 10.0;
        if tight {
            score -= 20.0; // poor fit elsewhere -> open new bin
        } else {
