    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let next_tight = 1.0 - ((pr - nxt) / cap);
            score -= 30.0 * next_tight * next_tight;
            // exact 2-chain match (post_residual == next_item_size)
            if (pr - nxt).abs() < 0.5 {
                score -= 25.0;
            }
        } else {
            // next item cannot follow into this residual: penalize dead space
            let gap = (pr - nxt).abs();
            score += 0.15 * gap;
        }
    }

