    // (packing into already-fragmented bins keeps large residuals available elsewhere).
    if pr < mean_residual {
        score -= 0.3 * (mean_residual - pr);
    } else {
        score += 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins can fit reasonably well.
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, softened if many items remain or no fitting bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 35.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0; // forced open
