}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    // Residuals in small bands (near multiples of common item sizes) are "usable";
    // mid-range dead zones are penalized.
    let post = post_residual;
    let class = post / 10; // 0..10 integer division band
    match class {
        0 => score -= 30.0,               // near-perfect fit
        1 => score -= 20.0,               // excellent
        2 => score -= 12.0,               // good
        3 => score -= 5.0,                // ok
        4 | 5 => score += 8.0,            // awkward dead zone
        6 => score += 2.0,                // half-full-ish, flexible
        7 => score += 0.0,
        8 => score -= 3.0,                // roomy, reusable
