        if post % 10 == 0 { harmony += 10.0; }
        if post % 20 == 0 { harmony += 6.0; }
        if post % 25 == 0 { harmony += 5.0; }
        if post % 50 == 0 { harmony += 4.0; }
        score -= harmony;
    }

    // Lookahead: does the next item fit the resulting residual?
    if next_item_size > 0 && next_item_size <= post {
        // Perfect pairing bonus if next item exactly fills the bin.
        if next_item_size == post {
            score -= 40.0;
        } else {
            let gap = (post - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / 50.0).max(0.0);
