        // if this bin is nearly full anyway.
        if post < 10 {
            score -= 5.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // have poor fits. Penalize the fresh bin mildly, scaled by stream position
    // and how many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If next item is huge, fresh bin is attractive reserve.
        if next_item_size >= 70 {
            score -= 12.0;
        }
