    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: post residual, non-linearly penalized (dead space hurts superlinearly).
    let mut score = pr + 0.35 * (pr * pr / cap) + 0.02 * (pr * pr * pr / (cap * cap));

    // Smooth coupling with stream progress: early on, keep bins tight (favor filling);
    // later, tolerate residual since future items are fewer.
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - progress);
    score *= progress_coupling;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Relative residual vs mean: prefer bins with more usable space when mean is tight.
    let rel = pr - mean_residual;
    score += 0.15 * rel * (1.0 + progress);

    // Lookahead: reward leaving a gap that fits the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        let fits = (pr >= nx) as f64;
        score -= 10.0 * fits * (1.0 - fit_gap / cap);
        // Penalize wasting almost the whole bin on a big next item it barely fits.
        score += 5.0 * fits * (nx / cap) * (pr - nx) / cap;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let scarcity = (fitting_bins_count as f64).max(1.0);
        score += 40.0 / scarcity + 20.0 * (1.0 - progress);
        // If the item fills a fresh bin substantially, opening is reasonable.
        score -= 30.0 * (item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic classes: partition post_residual into dead-space classes ----
    // Class A: post_residual <= 10 is essentially dead space -> strong penalty.
    if post_residual <= 10 {
        score += 40.0;
    }
    // Class B: post_residual in (10, 30] is half-dead; penalize mildly.
    else if post_residual <= 30 {
        score += 12.0;
    }
    // Class C: post_residual in (30, 50] can host mid items; neutral-to-good.
    else if post_residual <= 50 {
        score -= 6.0;
    }
    // Class D: post_residual > 50 keeps the bin highly reusable; reward.
    else {
        score -= 14.0;
    }

    // ---- Modulo arithmetic on post_residual vs. typical item granularity ----
    // Items are 1..=100; residuals divisible by common item chunks (10/20/25/50)
    // are more likely to be exactly filled by future items.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 8.0;
    } else {
        // Odd, awkward residuals waste space on average.
        score += 4.0;
    }

    // ---- Integer-division thresholds: how many "average items" fit afterward ----
    let avg_item = 40.0_f64.max(1.0);
    let fits_left = (post_residual as f64 / avg_item).floor();
    score -= 5.0 * fits_left;

    // ---- Lookahead coupling with next_item_size ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect or near-perfect lookahead match is gold.
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 30.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this bin's residual: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(60.0);
        }
    }

    // ---- Last-chance bin before opening a new one ----
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh bin: attractive early when few bins exist or item is large;
        // discouraged late in the stream when reuse is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 30.0 * progress + 0.3 * open_bins_count as f64;
        if item_size > 60 {
            score -= 20.0; // big items pair well with fresh bins
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // reserve fresh space for a big follower
        }
    }

    // ---- Mean-residual pressure: if open bins are already loose, prefer reuse ----
    score += 0.05 * (mean_residual - post_residual as f64);

    // ---- Small tie-break toward tighter fits ----
    score += 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are unusable.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        // Hard penalty making near-zero leftover attractive, tiny gaps terrible.
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as f64) <= item_size as f64 * 0.15 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot fit here; leftover is likely dead space.
        score += 8.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing residuals are large (poor fits) or bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 5.0 * open_bins_count as f64 * (1.0 - progress);
        // If mean residual across open bins is small, opening fresh is fine.
        if mean_residual < 20.0 {
            score -= 35.0;
        }
    }

    // Open-bin pressure: prefer reusing bins when many are open.
    score += 0.3 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the leftover: strongly reward tight two-item packing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
    }
    // Next item will NOT fit: penalize dead space, worse when it's small.
    if next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Reward bins tighter than the mean residual (good fill), punish loose ones.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count == 1 {
        score += 150.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize leaving tiny unusable fragments (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    }

    // Early in the stream, prefer keeping residual flexible (larger leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space: post_residual that is too small for any plausible item (min size 1,
    // but practically small leftovers waste capacity). Exponential penalty for tiny leftovers.
    if post_residual > 0 {
        let dead = 1.0 - (post_residual as f64) / 50.0;
        if dead > 0.0 {
            score += 8.0 * dead * dead;
        }
    } else {
        // Perfect fill is excellent.
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 6.0 * next_fit_quality;
    }
    // If next item cannot fit here, mild penalty scaled by how much this placement strands space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 2.0 * ((next_item_size - post_residual) as f64) / 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer new bins when
    // open bins are crowded (low mean residual) or when many bins are already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 12.0 - 10.0 * crowd - 4.0 * progress;
        // If no open bin fits at all, opening a new bin is necessary: make it cheap.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If next item is large and current placement would strand space, a fresh bin is safer.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && bin_residual > bin_capacity {
            score -= 3.0;
        }
    } else {
        // Existing-bin bonus scaled by how much better this bin's residual is vs the mean.
        let advantage = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score -= 3.0 * advantage.clamp(-1.0, 1.0);
        // Prefer using bins that are already partially filled (avoid bin proliferation).
        score -= 1.5;
    }

    // Time horizon: early in the stream, be conservative about tight fits (keep flexibility);
    // late in the stream, aggressively fill bins since fewer items remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Slight penalty for very large open_bins_count to discourage spreading items thin.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty growth.
    let mut score = pr as f64 + 30.0 * norm_pr * norm_pr;

    // Smooth coupling: post-residual value discounted/penalized by stream progress.
    // Late in the stream, tight fits matter more; early, hoarding capacity is fine.
    score += 25.0 * norm_pr * (1.0 - progress) - 15.0 * norm_pr * progress;

    // Dead-space curvature: residuals that are very small are great, mid-sized are bad.
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead coupling: reward if next item fits smoothly into post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_ratio = nxt / pr.max(1.0);
            score -= 12.0 * fit_ratio * (1.0 - (fit_ratio - 0.5) * (fit_ratio - 0.5));
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: smooth bonus when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Mild diversity pressure via mean residual.
    score += 0.05 * (mean_residual - pr).abs();

    // Slight penalty for proliferating bins early on.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (capacity fractions) ---
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // 0..1

    // Perfect fit: reward strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals that are too small for typical items
        // (items are 1..=100; residual < smallest plausible next item is waste)
        if post_residual < 10 {
            score += 60.0 * (10 - post_residual) as f64;
        }

        // Harmonic class: quantize post_residual into capacity-fraction classes
        // Class boundaries at 1/8 of capacity (12.5 units)
        let class = (post_residual * 8) / bin_capacity; // 0..8 integer division
        score -= 12.0 * class as f64; // larger residual class => better bin

        // Modulo-classes: residuals that divide cleanly into capacity fractions
        // are more reusable by future items of common sizes.
        let m16 = post_residual % 16;
        let m10 = post_residual % 10;
        // Penalize awkward remainders (not multiples of common item granularities)
        if m16 != 0 && m10 != 0 {
            score += 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0; // quarter-capacity friendly
        }
        if post_residual % 20 == 0 {
            score -= 4.0; // fifth-capacity friendly
        }

        // Lookahead coupling: does next_item_size fit harmonically?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // next item fits exactly or leaves a nice residual again
                let next_post = post_residual - next_item_size;
                if next_post == 0 {
                    score -= 120.0;
                } else if next_post % 10 == 0 {
                    score -= 25.0;
                }
                score -= (next_item_size as f64).min(post_f) * 0.3;
            } else {
                // next item won't fit here; residual must hold something else.
                // Penalize only mildly since other items may follow.
                score += 10.0;
                // If next item is large and this bin is nearly the only option,
                // prefer bins whose leftover stays in a coarse class.
                if next_item_size > bin_residual {
                    score -= 5.0;
                }
            }
        }

        // Last-chance bin: strongly prefer using it to avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Fraction-of-capacity nonlinear shaping: quadratic in leftover fraction
        score += 30.0 * frac * frac;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin baseline: its "post_residual" is capacity - item_size.
        // Prefer a fresh bin when the current item leaves a very clean residual
        // (perfect harmonic class) or when no open bin fits well.
        if post_residual == 0 {
            score -= 900.0;
        }
        if post_residual % 25 == 0 || post_residual % 20 == 0 {
            score -= 30.0;
        }
        // If many bins fit the item, discourage opening a new one
        score += 15.0 * fitting_bins_count as f64;
        // Late in the stream, avoid bin proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild global pressure: when mean residual is high, favor consolidation
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit gets a strong reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Penalize leaving a gap that is too small for the minimum item (1..10 range guard)
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 15.0;
    }

    // Reward a fit that also accommodates the next item (lookahead synergy)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if next item cannot fit anywhere afterwards in this bin's gap
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Deviation from mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: make it moderately attractive only when current fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 + (post_residual as f64 - item_size as f64).abs() * 0.1;
    }

    // Late-stream tightening: as stream progresses, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between
    // post_residual and the next item's size (perfect chain).
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - look).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect 2-step match: place here
        } else if post >= look {
            // next item fits here afterwards: mild reward, tighter is better
            score -= 15.0 * (1.0 - diff / look.max(1.0));
        } else {
            // next item would NOT fit after this placement: penalize
            score += 10.0 + 25.0 * (diff / (bin_capacity as f64));
        }
    } else {
        // last item: prefer tightest fit
        score -= 5.0;
    }

    // Penalize creating unusable dead space relative to the smallest
    // conceivable future item (items can be as small as 1).
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins already tighter than average are
    // good candidates; very loose bins get a mild penalty.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, offset when stream is early
        // or many bins are open (amortization) or the fit is poor.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = (bin_capacity - item_size.min(bin_capacity)) as f64;
        score += 18.0 - 10.0 * progress - 0.05 * open_bins_count as f64
                 - 0.2 * waste;
    }

    // Slight preference for bins whose post-residual is a "nice" small value
    // (reduces fragmentation into tiny unusable slivers).
    if post_residual > 0 && post_residual <= 5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (waste pockets).
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if post_residual < 10 {
            score += 25.0 * (1.0 - dead);
        } else if post_residual < item_size.max(10) {
            // pocket can't fit even the smallest future item of similar size
            score += 6.0;
        }
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 14.0 * next_tight;
        } else {
            // next item won't fit here; mild penalty for leaving a bin that strands lookahead
            score += 3.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        // many options: favor the ones that keep flexibility (larger post residual)
        score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in the stream, prefer consolidating into open bins
    // (fewer bins); late in the stream, pure residual quality matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 4.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is below the mean (compact the emptier-side bins).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;

    // New-bin candidate: only attractive when item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 22.0 * pressure * big_item - 8.0 * (1.0 - progress) * big_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr_norm * (1.0 + 0.8 * progress) + 0.9 * pr_norm * pr_norm;

    // Penalize large dead space more as the stream matures (smooth cubic term)
    score += 0.6 * pr_norm.powi(3) * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= 0.4 * (1.0 - pr_norm) * progress;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        score += 12.0 * (1.0 - tight).clamp(0.0, 1.0) + 3.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 1.5 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 0.5 * (1.0 - pr / nxt.max(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins grouped by residual fraction of capacity.
    // Class 0: residual <= 10 (nearly full, great). Class 1: 11..=25. Class 2: 26..=50. Class 3: >50.
    let class = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 0 }
        else if post_residual <= 25 { 1 }
        else if post_residual <= 50 { 2 }
        else { 3 };
    score += class as f64 * 12.0;

    // Exact-fill reward (modulo-style): residual divisible by item or perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if bin_residual % item_size == 0 && post_residual <= item_size {
        score -= 25.0; // creates a "harmonic" residual usable by small items
    }

    // Dead-space penalty: residual in awkward zone (26..=40) wastes capacity.
    if post_residual >= 26 && post_residual <= 40 {
        score += 18.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual && (post_residual - next_item_size) <= 10 {
            score -= 35.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 10.0; // next item would prefer a different bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Penalize opening new bins early; allow later when residuals are low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 25.0 * progress;
        if post_residual == bin_capacity {
            score -= 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        }
    }

    // Prefer bins with residual far below mean (tight bins first).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 65.0;
        } else if post_residual >= next_item_size {
            score -= 45.0 / (1.0 + match_gap / 8.0);
            let post2 = post_residual - next_item_size;
            if post2 == 0 {
                score -= 28.0;
            } else if post2 <= 8 {
                score -= 12.0;
            }
            // Chain quality: if the item after next is small, small post2 is fine.
            if next_item_size > 0 && post2 > 0 && post2 < next_item_size / 4 {
                score -= 4.0;
            }
        } else {
            // Next item won't chain: penalize dead space, but scale with how
            // badly it misses so near-misses aren't over-penalized.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss + if miss > 25.0 { 8.0 } else { 0.0 };
        }
    } else {
        score += 0.3 * post_residual as f64;
    }

    // Relative-to-mean coupling: tighter-than-average bins are more valuable.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }
    // Scarcity pressure: few fitting bins => keep them alive.
    if fitting_bins_count >= 2 && fitting_bins_count <= 3 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate decision.
    if bin_residual == bin_capacity {
        let item_f = item_size as f64;
        let next_f = next_item_size as f64;
        // Fresh bin is attractive when item exceeds typical residuals or
        // when it would leave an awkward sliver in an existing bin.
        let awkward = post_residual > 0 && post_residual < bin_capacity / 12;
        if item_f > mean_residual * 1.1 || awkward {
            score -= 15.0;
        } else {
            score += 25.0;
        }
        // Late stream: opening new bins is expensive; resist harder.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 {
            score += 10.0 * progress;
        }
        // If next item is large, a fresh bin with room for it is valuable.
        if next_f > 0.0 && bin_capacity as f64 - item_f >= next_f {
            score -= 10.0;
