    }

    // Late-stream tightening: waste matters more as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * progress * post_residual as f64;

    // Exact fit is always superb.
    if post_residual == 0 {
        score -= 55.0;
    }

    score
}

