    // Scarcity pressure: when few bins can fit the item, protect them.
    if fitting_bins_count >= 2 && fitting_bins_count <= 3 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate logic: penalize by default, but allow escape when the
    // item would leave a large ugly gap in every plausible bin, or when the
    // item is nearly a full bin itself (fresh bin wastes almost nothing).
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 > mean_residual {
            score -= 25.0;
