            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 20.0;
        }
        if open_bins_count > 6 && frac <= 0.5 && fitting_bins_count >= 2 {
            score += 12.0;
        }
        return score;
    }

