            score += 20.0;
        }
        if open_bins_count > 6 && item_f <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Late-stream tightening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
