        if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 6 {
            score += 5.0;
        }
        // tiny leftovers are fine (near-perfect packing)
        if post_residual > 0 && post_residual < 5 {
            score -= 6.0;
        }
    }

    // Global consolidation pressure
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
