    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Compare against mean residual: placing into a bin whose residual is
    // far below average keeps big holes alive elsewhere; prefer bins that
    // are already tight (low residual) for large items.
    score += 0.5 * (bin_residual as f64 - mean_residual).max(-50.0);

    // Last-chance bin: if this is the only bin that fits, use it rather
    // than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral-ish baseline so it only wins when no open
    // bin offers a decent fit. Slightly cheaper early when many bins open.
    if bin_residual == bin_capacity {
        score = 55.0 - 0.1 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= next_item_size as f64 * 0.1;
        }
    }

    score
}

