pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64); // penalize large dead space quadratically
        // Penalize residuals that are too small to fit the smallest plausible item
        if pr < 10.0 {
            score += 50.0;
        }
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            score -= 60.0;
        } else {
            score += 40.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 300.0;
    } else if fitting_bins_count > 1 {
        score += 10.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer filling bins that are already low-residual relative to the mean.
    score += (bin_residual as f64 - mean_residual) * 0.8;

    // Mild preference for reusing existing bins vs opening new ones, growing with stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity as f64 - item_size as f64);
        score = 150.0 + waste * 0.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 80.0; // new bin also fits next item
        }
        if fitting_bins_count == 1 {
            score += 200.0; // a real bin exists that fits; avoid opening new
        }
    }

    // Slight preference to keep number of open bins from exploding early.
    score += (open_bins_count as f64) * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let item_f = item_size as f64;

    // Density-aware term: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_f / bin_residual.max(1) as f64;
    score -= 22.0 * fill_ratio;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals too small for typical items (graded)
        if post_residual < 10 {
            score += 60.0 * (10 - post_residual) as f64;
        } else if post_residual <= 20 {
            score += 8.0;
        }

        // Harmonic class quantization
        let class = (post_residual * 8) / bin_capacity;
        score -= 12.0 * class as f64;

        // Modulo-class friendliness
        let m16 = post_residual % 16;
        let m10 = post_residual % 10;
        if m16 != 0 && m10 != 0 {
            score += 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0;
        }
        if post_residual % 20 == 0 {
            score -= 4.0;
        }

        // Lookahead: two-step chain anticipation (fine-grained + graded decay)
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 90.0;
            } else if next_item_size <= post_residual {
                let next_post = post_residual - next_item_size;
                if next_post == 0 {
                    score -= 130.0;
                } else if next_post <= 10 {
                    score -= 18.0;
                } else if next_post % 10 == 0 {
                    score -= 25.0;
                } else if (next_post as f64) <= 0.5 * mean_residual {
                    score -= 6.0;
                }
                // graded decay reward: tight 2-step chains preferred
                score -= 50.0 / (1.0 + next_post as f64 / 12.0);
                score -= (next_item_size as f64).min(post_f) * 0.3;
                // NEW: three-step chain anticipation (borrowed from best heuristic)
                if next_post >= next_item_size {
                    let post3 = next_post - next_item_size;
                    score -= 6.0;
                    if post3 == 0 {
                        score -= 10.0;
                    }
                }
                // NEW: dead-space trap detection — leftover too small for next item
                if next_post > 0 && next_post < next_item_size && (next_post as f64) < 0.25 * mean_residual {
                    score += 7.0;
                }
            } else {
                // Next item won't fit; penalize proportionally to the gap,
                // weighted by how hard the next item is to place.
                let next_hardness = next_item_size as f64 / cap_f;
                score += (0.4 + 0.5 * next_hardness) * (next_item_size as f64 - post_f);
                // NEW: penalize residuals just barely too small for the next item
                if next_item_size - post_residual <= 6 {
                    score += 5.0;
                }
            }
        }

        // Last-chance / scarcity protection
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 55.0;
        } else if fitting_bins_count >= 2 && fitting_bins_count <= 3 && bin_residual < bin_capacity {
            score -= 10.0;
        }

        // Relative-to-mean coupling
        score += 0.14 * (post_f - mean_residual);

        // Fraction-of-capacity quadratic shaping
        score += 30.0 * (post_f / cap_f) * (post_f / cap_f);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 900.0;
        }
        if post_residual % 25 == 0 || post_residual % 20 == 0 {
            score -= 30.0;
        }
        // Nearly-full items belong in a fresh bin: waste is tiny.
        if item_f > 0.85 * cap_f {
            score -= 45.0;
        }
        // If the item exceeds typical mean residual, a fresh bin is cleaner.
        if item_f > mean_residual {
            score -= 25.0;
        }
        // Lookahead: if the next item would exactly consume the fresh-bin leftover,
        // opening a new bin sets up a perfect chain.
        if next_item_size > 0 && next_item_size < item_size {
            let fresh_post = bin_capacity - item_size;
            if fresh_post == next_item_size {
                score -= 80.0;
            } else if fresh_post > next_item_size && (fresh_post - next_item_size) <= 10 {
                score -= 20.0;
            }
        }
        // Hoarding risk: many open bins with high mean residual → fresh bin OK.
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 10.0;
        }
        // Many fitting bins: discourage proliferation (stronger when scarcity is low).
        score += 18.0 * fitting_bins_count as f64;
        // NEW: stronger proliferation guard — good fits exist among open bins
        if fitting_bins_count > 2 && item_f <= mean_residual {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_f <= 0.8 * mean_residual {
            score += 20.0;
        }
        if open_bins_count > 6 && item_f <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Late-stream tightening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Mild penalty for leaving a large gap after placement in existing bins,
        // encouraging compaction of open bins.
        if next_item_size > 0 && post_residual > next_item_size {
            score += 0.1 * (post_residual - next_item_size) as f64;
        }
        // NEW: penalize residuals just barely too small for the next item
        if next_item_size > post_residual && next_item_size - post_residual <= 6 && post_residual > 0 {
            score += 5.0;
        }
    }

    // Global consolidation pressure
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin ( item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize ) -> f64 {
