        }
    }
    let progress = step_index as f64 / total_items . max ( 1 ) as f64 ;
    score += 0.4 * progress * post_residual as f64 ;
    if post_residual == 0 {
        score -= 50.0 ;
    }
    // refinement: stronger preference for exact-fill chains late in the stream
    if post_residual == 0 && progress > 0.5 {
        score -= 6.0 * progress ;
    }
    // dead-space avoidance: residual too small for average future demand
    if post_residual > 0 && ( post_residual as f64 ) < 0.12 * bin_capacity as f64 && next_item_size > post_residual {
