    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * (1.0 - progress) * (1.0 - progress);
    score += 20.0 * poly;

    // Tight fits (small post_residual) are rewarded more as stream progresses
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (30.0 + 40.0 * progress);

    // Penalize dead space relative to mean residual of open bins
    let dead = (norm_post * cap - mean_residual).abs();
    score += 0.15 * dead * (1.0 + progress * progress);

