    // Discard near-empty usage of many open bins; encourage consolidation
    if open_bins_count > 1 {
        score += 5.0 * (norm_post - 0.5) * (open_bins_count as f64).sqrt();
    }

    // Lookahead: reward leaving space usable by the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            score += 10.0 * (ni - pr) / cap;
        }
    }

    // Mild preference for opening a new bin early vs late
    score += progress * 8.0 * (1.0 - norm_post);

    score
}

