pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residual divisible into nice chunks is valuable
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Small dead space is bad (unusable), moderate residual reusable
    if pr < 10.0 {
        score += 60.0; // dead space penalty
    } else {
        // reward residuals that are harmonic class: divisible by common item sizes
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                harmony += 8.0;
            }
        }
        score -= harmony;

        // reward residual >= next item (lookahead chaining)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
            // exact chain: post_residual == next_item_size -> perfect
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else if next_item_size > 0 {
            score += 10.0; // next item won't fit here
        }

        // capacity fraction classes: residual in [25,50] vs [50,75] etc.
        let frac = pr / cap;
        if frac >= 0.5 {
            score -= 15.0;
        } else if frac >= 0.25 {
            score -= 5.0;
        } else {
            score += 8.0;
        }
    }

    // Last fitting bin: strong incentive to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 45.0;
        // early in stream, opening bins can be fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for tighter (fuller) bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Waste relative to mean residual: avoid leaving outliers
    score += (pr - mean_residual).abs() * 0.05;

    score
}

