                score -= (next_item_size as f64).min(post_f) * 0.3;
                // three-step chain bonus
                if next_post >= next_item_size {
                    let post3 = next_post - next_item_size;
                    score -= 6.0;
                    if post3 == 0 {
                        score -= 8.0;
                    }
                }
                // dead-space penalty: leftover too small for next item
                if next_post > 0 && next_post < next_item_size && (next_post as f64) < mean_residual * 0.25 {
                    score += 7.0;
                }
            } else {
                let next_hardness = next_f / cap_f;
                score += (0.45 + 0.45 * next_hardness) * (next_f - post_f);
                // barely-too-small residual: penalize mildly
                if next_item_size - post_residual <= 6 {
                    score += 5.0;
                }
            }
        } else {
            score += 0.3 * post_f;
        }

        // Last-chance / scarcity protection
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 55.0;
        } else if fitting_bins_count >= 2 && fitting_bins_count <= 3 && bin_residual < bin_capacity {
            score -= 10.0;
        }

        // Relative-to-mean coupling
        score += 0.14 * (post_f - mean_residual);

        // Fraction-of-capacity quadratic shaping
        let frac = post_f / cap_f;
        score += 30.0 * frac * frac;

        // Multiple fitting options: prefer spreading less / tighter fits
        if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
            score += 2.0 * (fitting_bins_count as f64 - 1.0);
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 900.0;
        }
        if post_residual % 25 == 0 || post_residual % 20 == 0 {
            score -= 30.0;
        }
        // Nearly-full items belong in a fresh bin: waste is tiny.
        if item_f > 0.85 * cap_f {
            score -= 45.0;
        }
        // If the item exceeds typical mean residual, a fresh bin is cleaner.
        if item_f > mean_residual {
            score -= 25.0;
        }
        // Lookahead: perfect chain setup from a fresh bin.
        if next_item_size > 0 && next_item_size < item_size {
            let fresh_post = bin_capacity - item_size;
            if fresh_post == next_item_size {
                score -= 80.0;
            } else if fresh_post > next_item_size && (fresh_post - next_item_size) <= 10 {
                score -= 20.0;
            }
        }
        // Hoarding risk: many open bins with high mean residual → fresh bin OK.
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 10.0;
        }
        // Discourage proliferation when decent fits exist.
        score += 18.0 * fitting_bins_count as f64;
        if fitting_bins_count > 2 && item_f <= mean_residual {
            score += 15.0;
        }
        if fitting_bins_count >= 1 && item_f <= mean_residual * 0.8 {
            score += 20.0;
        }
        if open_bins_count > 6 && item_f <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Late-stream tightening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Mild penalty for leaving a large gap after placement in existing bins.
        if next_item_size > 0 && post_residual > next_item_size {
            score += 0.1 * (post_residual - next_item_size) as f64;
        }
        // Penalize residuals just barely too small for the next item.
        if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 6 {
            score += 8.0;
        }
    }

    // Global consolidation pressure + progress-weighted residual shaping
    score -= 0.05 * mean_residual;
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * progress * post_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (too small for the smallest
    // plausible item, size 1..~20) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Post-residual that cannot host the lookahead item is dead space for k=2.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins,
    // reward consolidating into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Empty new-bin candidate: penalize so it only wins when all open bins
    // are terrible fits (its post_residual = capacity - item_size is large,
    // so the base term already hurts it; add extra guard).
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Late in the stream, tighten consolidation further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

