pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how tight the leftover is.
            let leftover_after_next = post_residual - next_item_size;
            score -= 100.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize wasted setup potential,
            // worse when post_residual is small (dead space).
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Dead-space penalty: small post residuals that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Compare against mean residual: placing into a bin whose residual deviates
    // favorably from the mean keeps the bin pool balanced.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late in the stream, prefer tighter packing (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin ( item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize ) -> f64 {
