pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: strongly prefer using a bin when it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is doubly valuable; if next item would have fit this bin
    // better, discourage wasting the space.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 50.0;
        } else if next_item_size as u32 > post_residual {
            // next item won't fit here anyway; mild bonus for compacting now
            score -= 10.0;
