            // next item fits in leftover: penalize leaving awkward mid-range gaps
            let gap = (post_residual - next_item_size) as f64;
            score += 0.15 * gap;
        }
    }

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, pack aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let time_bias = 20.0 * progress;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more early, less late.
        score += 15.0 * (1.0 - progress) + 5.0;
    } else {
        score -= time_bias;
