    // Global state: many open bins with high mean residual -> consolidate.
    if bin_residual as f64 > mean_residual && open_bins_count > 3 {
        score -= 8.0;
    } else if (bin_residual as f64) < mean_residual * 0.5 {
        // bin is nearly full relative to average: good place to dump item
        score -= 12.0;
    }

    // Mild penalty for opening bins when many already exist.
    if bin_residual == bin_capacity {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

