        if item_f > 0.85 * cap_f {
            score -= 35.0 ;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 10.0 ;
        }
        // discourage opening a new bin when decent fits exist among open bins
        if fitting_bins_count > 2 && item_f <= mean_residual {
            score += 15.0 ;
        }
        if fitting_bins_count >= 1 && item_f <= mean_residual * 0.8 {
            score += 20.0 ;
        }
        if open_bins_count > 6 && item_f <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 12.0 ;
        }
        // large items late in the stream benefit from a fresh bin more often
        let progress = step_index as f64 / total_items . max ( 1 ) as f64 ;
        if item_f > 0.7 * cap_f && progress > 0.5 {
            score -= 8.0 ;
        }
    } else {
        if next_item_size > 0 && post_residual > next_item_size {
            score += 0.1 * ( post_residual - next_item_size ) as f64 ;
        }
        if post_residual > 0 && post_residual < 12 && next_item_size > post_residual {
            score += 8.0 ;
        }
        // reward near-tight fits relative to item size, sharpened for very tight fits
        if waste_ratio > 0.9 {
            score -= 9.0 ;
        } else {
            score -= 6.0 * waste_ratio ;
        }
        // penalize residuals just barely too small for the next item
        if next_item_size > post_residual && next_item_size - post_residual <= 6 && post_residual > 0 {
            score += 5.0 ;
        }
        if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
            score += 2.0 * ( fitting_bins_count as f64 - 1.0 ) ;
        }
        if post_residual > 0 && post_residual < 5 {
            score -= 6.0 ;
        }
        // avoid fragmenting a large residual with a tiny item when bigger items remain
        if item_f < 0.2 * cap_f && post_f > 2.5 * item_f && next_item_size > item_size {
            score += 3.0 ;
        }
    }
    let progress = step_index as f64 / total_items . max ( 1 ) as f64 ;
    score += 0.4 * progress * post_f ;
    if post_residual == 0 {
        score -= 50.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post residual), smoothed non-linearly.
    let mut score = post * (1.0 + 0.5 * post / cap);

    // Smooth coupling of tightness with stream progress: early on, keep bins
    // flexible; later, prioritize packing tightly.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving room for the next item if it fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack_fit) * (1.0 - slack_fit);
        } else {
            // Penalize blocking the next item proportionally to the gap.
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Slight penalty when this bin's residual is far above mean residual
    // (keeps a diverse residual portfolio).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Mild pressure to consolidate into fewer bins as the stream matures.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with a small progress-dependent
    // cost so late in the stream we prefer reusing open bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the leftover: strongly reward tight two-item packing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        // chain lookahead: same item could fit again after the next one
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 10.0;
            }
        }
        // dead-space: leftover after next is unusably small for next item
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
    }
    // Next item will NOT fit: penalize dead space, worse when it's small.
    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
        if post_residual > 0 && gap <= 6 {
            score += 6.0; // barely-too-small residual is wasted potential
        }
    }

    // Reward bins tighter than the mean residual (good fill), punish loose ones.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Reward tightness of the actual placement relative to bin residual.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Last-chance bin: avoid wasting it unless the fit is very tight.
    if fitting_bins_count == 1 {
        score += 150.0 * (post_residual as f64 / bin_capacity as f64);
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        // with alternatives, mild penalty favors spreading load
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving tiny unusable fragments (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    }
    if post_residual == 0 {
        score -= 50.0;
    }

    // Progress term: keep flexibility early, prefer closing bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;
    score += 0.25 * progress * (post_residual as f64);

    // NEW-BIN CANDIDATE handling: default is unattractive; open only when
    // the item is large relative to what open bins can absorb.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
        // discourage opening a new bin when decent fits exist among open bins
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * bin_capacity as f64 && fitting_bins_count >= 2 {
            score += 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let item_f = item_size as f64;

    // Density-aware term: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_f / bin_residual.max(1) as f64;
    score -= 22.0 * fill_ratio;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals too small for typical items (graded)
        if post_residual < 10 {
            score += 60.0 * (10 - post_residual) as f64;
        } else if post_residual <= 20 {
            score += 8.0;
        }

        // Harmonic class quantization
        let class = (post_residual * 8) / bin_capacity;
        score -= 12.0 * class as f64;

        // Modulo-class friendliness
        let m16 = post_residual % 16;
        let m10 = post_residual % 10;
        if m16 != 0 && m10 != 0 {
            score += 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0;
        }
        if post_residual % 20 == 0 {
            score -= 4.0;
        }

        // Lookahead: two-step chain anticipation (fine-grained + graded decay)
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 90.0;
            } else if next_item_size <= post_residual {
                let next_post = post_residual - next_item_size;
                if next_post == 0 {
                    score -= 130.0;
                } else if next_post <= 10 {
                    score -= 18.0;
                } else if next_post % 10 == 0 {
                    score -= 25.0;
                } else if (next_post as f64) <= 0.5 * mean_residual {
                    score -= 6.0;
                }
                // graded decay reward: tight 2-step chains preferred
                score -= 50.0 / (1.0 + next_post as f64 / 12.0);
                score -= (next_item_size as f64).min(post_f) * 0.3;
                // NEW: three-step chain bonus
                if next_post >= next_item_size {
                    let post3 = next_post - next_item_size;
                    score -= 8.0;
                    if post3 == 0 {
                        score -= 10.0;
                    } else if post3 <= 6 {
                        score -= 4.0;
                    }
                }
            } else {
                // Next item won't fit; penalize proportionally to the gap,
                // weighted by how hard the next item is to place.
                let next_hardness = next_item_size as f64 / cap_f;
                score += (0.4 + 0.5 * next_hardness) * (next_item_size as f64 - post_f);
                // NEW: penalize residuals just barely too small for the next item
                if next_item_size - post_residual <= 6 {
                    score += 5.0;
                }
            }
        } else {
            score += 0.2 * post_f;
        }

        // Last-chance / scarcity protection
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 55.0;
        } else if fitting_bins_count >= 2 && fitting_bins_count <= 3 && bin_residual < bin_capacity {
            score -= 10.0;
        }

        // Relative-to-mean coupling
        score += 0.14 * (post_f - mean_residual);

        // Fraction-of-capacity quadratic shaping
        score += 30.0 * frac_of(post_f, cap_f) * frac_of(post_f, cap_f);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if post_residual == 0 {
            score -= 900.0;
        }
        if post_residual % 25 == 0 || post_residual % 20 == 0 {
            score -= 30.0;
        }
        // Nearly-full items belong in a fresh bin: waste is tiny.
        if item_f > 0.85 * cap_f {
            score -= 45.0;
        }
        // If the item exceeds typical mean residual, a fresh bin is cleaner.
        if item_f > mean_residual {
            score -= 25.0;
        }
        // Lookahead: if the next item would exactly consume the fresh-bin leftover,
        // opening a new bin sets up a perfect chain.
        if next_item_size > 0 && next_item_size < item_size {
            let fresh_post = bin_capacity - item_size;
            if fresh_post == next_item_size {
                score -= 80.0;
            } else if fresh_post > next_item_size && (fresh_post - next_item_size) <= 10 {
                score -= 20.0;
            }
        }
        // Hoarding risk: many open bins with high mean residual → fresh bin OK.
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 10.0;
        }
        // Many fitting bins: discourage proliferation (stronger when scarcity is low).
        score += 18.0 * fitting_bins_count as f64;
        if fitting_bins_count > 2 && item_f <= mean_residual {
            score += 15.0;
        }
        if open_bins_count > 6 && item_f <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 12.0;
        }
        // Late-stream tightening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Mild penalty for leaving a large gap after placement in existing bins,
        // encouraging compaction of open bins.
        if next_item_size > 0 && post_residual > next_item_size {
            score += 0.1 * (post_residual - next_item_size) as f64;
        }
        // NEW: dead-space guard — tiny unusable leftovers are bad unless perfect fits
        if post_residual > 0 && post_residual < 5 {
            score -= 6.0;
        }
    }

    // Global consolidation pressure
    score -= 0.05 * mean_residual;

    score
}

#[inline]
fn frac_of(v: f64, cap: f64) -> f64 {
    v / cap
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity-fraction bands and integer-division structure.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fine dead space (< 10) is nearly unusable: penalize sharply.
    if post_residual < 10 {
        score += 25.0;
    } else {
        // Modulo-10 harmonic class: leftovers that are multiples of 10
        // match the smallest item class well.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        // Integer-division thresholds on usable leftovers.
        let usable_quotient = post_residual / 10; // how many 10-units fit
        score -= 2.0 * (usable_quotient as f64).sqrt() * 3.0;

        // Fraction-of-capacity bands: prefer residuals in "harmonic" bands
        // (multiples of capacity quarters) that pair with common sizes.
        let quarter = (pr / (cap / 4.0)).round();
        if (pr - quarter * cap / 4.0).abs() < 1.0 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward if next item fits the post residual
    // (chaining placements), penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Exact chain: post residual equals next item size exactly.
            if next_item_size == post_residual {
                score -= 12.0;
            }
            // Harmonic divisibility: next item divides post residual evenly.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use the leftover: dead-space risk grows
            // with how close next_item_size is to post_residual.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 10.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when the
    // current item leaves a "clean" harmonic residual elsewhere unlikely.
    if bin_residual == bin_capacity {
        // New bin baseline: its post residual equals capacity - item_size.
        // Prefer opening a new bin for large items that leave small residue.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Discourage new bins when many open bins still have room.
        score += 3.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild tie-break toward bins below mean residual (balancing).
    if pr > mean_residual {
        score += 1.5;
    } else {
        score -= 1.5;
    }

    score
}

pub fn score_bin ( item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize ) -> f64 {
