    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the smallest
    // future item (size 1..100 interface) are pure waste. Penalize small gaps hard.
    if post_residual > 0 {
        // Waste grows super-linearly as the gap shrinks below a useful threshold.
        let gap = post_residual as f64;
        if gap < 20.0 {
            score += (20.0 - gap) * (20.0 - gap) * 0.5;
        }
        // Perfect fit is golden.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Dead space relative to capacity: reward tight packing.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use this gap: penalize proportionally to gap uselessness.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // ones rather than spreading; a new-bin candidate (residual == capacity) gets
    // penalized more when many bins are already open.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 3.0;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Stream progression: early on, allow slightly more spreading to build good
    // anchors; late in the stream, tighten packing aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tighter bins) to keep a pool of large residuals available.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
