                if two_post == 0 {
                    score -= 30.0;
                } else if two_post <= 6 {
                    score -= 14.0;
                }
            }
            // three-step chain potential (deep lookahead when stream is long)
            if leftover_after_next >= 3 * next_item_size {
                score -= 6.0;
                if remaining > 96.0 {
                    let three_post = leftover_after_next - 3 * next_item_size;
                    if three_post == 0 {
                        score -= 12.0;
                    } else if three_post <= 5 {
                        score -= 6.0;
                    } else {
