            score += 10.0;
        }
        // bonus when residual is a multiple of the next item (perfect tiling)
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        // consumption ratio: near-total consumption of residual by next item is ideal
        let consumed_frac = next_item_size as f64 / post_f.max(1.0);
        if consumed_frac > 0.85 {
