                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            // moderate stranded residual but very long stream: savings outweigh waste
            if post_f <= 0.10 * cap_f && remaining > 220.0 {
                score -= 10.0;
            }
