pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let mut score = post_f;

    // Perfect 2-step fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        // chain lookahead
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 12.0;
            }
            if leftover_after_next >= 3 * next_item_size {
                score -= 4.0;
                if remaining > 96.0 {
                    score -= 4.0;
                }
            }
            // three-step exact landing bonus (borrowed from best)
            let two_post = leftover_after_next - next_item_size;
            if two_post == 0 {
                score -= 30.0;
            } else if two_post <= 6 {
                score -= 14.0;
            } else if two_post >= next_item_size {
                let three_post = two_post - next_item_size;
                if three_post == 0 && remaining > 96.0 {
                    score -= 14.0;
                } else if three_post <= 5 && remaining > 48.0 {
                    score -= 8.0;
                }
                // pair-coverage: current item also fits after next two
                if three_post >= item_size {
                    score -= 3.5;
                }
            }
        }
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0 - 4.0 * leftover_after_next as f64;
        } else if leftover_after_next <= 8 {
            score -= 14.0;
        }
        // small reusable remainder that fits either current or next item
        if leftover_after_next > 0 && leftover_after_next <= 10 && leftover_after_next >= item_size.min(next_item_size) {
            score -= 4.0;
        }
        // dead-space check
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // multiple-of-next tiling bonus
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        // reward absorbing a big chunk of the next item size
        score -= (next_item_size as f64).min(post_f) * 0.35;
        // consumed-fraction bonus (borrowed): nearly-emptying the bin with next item
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // curvature: keep post residuals near the next item size slightly preferred
        score += 0.08 * (leftover_after_next as f64 - next_item_size as f64).abs();
    }

    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        let next_hardness = next_item_size as f64 / cap_f;
        score += (0.35 + 0.55 * next_hardness) * gap as f64;
        if post_residual > 0 && gap <= 6 {
            score += 6.0;
        }
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
        }
        // moderate stranded residual on a very long stream: fresh bin preferred
        if bin_residual == bin_capacity && post_f <= 0.10 * cap_f && remaining > 220.0 {
            score -= 10.0;
        }
        // fresh-bin sizing gate (borrowed): tiny next item + many open bins -> keep fresh bin closed
        if bin_residual == bin_capacity && next_hardness < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        // mid-stream fresh-bin damping (borrowed)
        if bin_residual == bin_capacity && open_bins_count > 8 && remaining > 128.0 && next_hardness < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_hardness);
        }
    }

    // Reward bins tighter than the mean residual.
    score -= (mean_residual - post_f) * 0.5;

    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Quadratic fullness pull plus residual-class term (borrowed).
    let wf = post_f / cap_f;
    score += 32.0 * wf * wf;
    let class = (post_residual * 8) / bin_capacity;
    score -= 12.0 * class as f64;

    // Fine-grained small-residual shaping (borrowed from best).
    if post_residual > 0 {
        if post_residual < 8 {
            score -= 35.0;
        } else if post_residual < 12 {
            score += 45.0 * (12 - post_residual) as f64;
        } else if post_residual <= 20 {
            score += 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 7.0;
        }
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // stranded-near-miss shaping (borrowed)
        if next_item_size > post_residual && post_residual >= 8 && post_residual < next_item_size {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - wf);
    } else if fitting_bins_count >= 2 && fitting_bins_count <= 3 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Many fitting bins: keep tight bins tight.
    if fitting_bins_count > 3 && bin_residual < bin_capacity && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mild quadratic residual pressure when few bins compete (borrowed).
    if fitting_bins_count <= 2 && post_residual > 0 {
        score += 0.05 * (post_f * post_f) / cap_f;
    }

    // Late-stream reuse penalty.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
        score += 5.0;
    }

    // Progress term.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    // NEW-BIN CANDIDATE handling.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - wf);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            // large next item with many open bins: fresh bin absorbs it well
            if open_bins_count > 6 && remaining > 200.0 && next_item_size as f64 > 0.6 * cap_f {
                score -= 8.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        // Endgame guard: prefer filling existing bins near the end.
        if remaining < 12.0 {
            score += 55.0;
        }
        // extended endgame ramp (borrowed): consolidate before final phase
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
    }

    score
}

