        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // multiple-of-next tiling bonus
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        // reward absorbing a big chunk of the next item size
        score -= (next_item_size as f64).min(post_f) * 0.35;
        // consumed-fraction bonus: nearly-emptying the bin with next item
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // curvature: keep post residuals near the next item size slightly preferred
        score += 0.08 * (leftover_after_next as f64 - next_item_size as f64).abs();
        // NEW: small-residual exact-fit window — a leftover that matches a
        // typical small item (< 12) is prime real estate on long streams
        if leftover_after_next > 0 && leftover_after_next <= 6 && remaining > 200.0 {
            score -= 6.0;
        }
    }

    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        let next_hardness = next_item_size as f64 / cap_f;
        score += (0.35 + 0.55 * next_hardness) * gap as f64;
        if post_residual > 0 && gap <= 6 {
            score += 6.0;
        }
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
        }
        // moderate stranded residual on a very long stream: fresh bin preferred
        if bin_residual == bin_capacity && post_f <= 0.10 * cap_f && remaining > 220.0 {
            score -= 10.0;
        }
        // fresh-bin sizing gate: tiny next item + many open bins -> keep fresh bin closed
        if bin_residual == bin_capacity && next_hardness < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        // mid-stream fresh-bin damping
        if bin_residual == bin_capacity && open_bins_count > 8 && remaining > 128.0 && next_hardness < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_hardness);
        }
    }

    // Reward bins tighter than the mean residual.
    score -= (mean_residual - post_f) * 0.5;

    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Quadratic fullness pull plus residual-class term.
    let wf = post_f / cap_f;
    score += 32.0 * wf * wf;
    let class = (post_residual * 8) / bin_capacity;
    score -= 12.0 * class as f64;

