        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0 - 4.0 * leftover_after_next as f64;
        } else if leftover_after_next <= 8 {
            score -= 14.0;
        }
        // small reusable remainder that fits either current or next item
        if leftover_after_next > 0 && leftover_after_next <= 10 && leftover_after_next >= item_size.min(next_item_size) {
            score -= 4.0;
        }
        // dead-space check
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // multiple-of-next tiling bonus
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
