        // by remaining stream so late placements tolerate larger leftovers
        let curvature = 0.08 + 0.04 * (1.0 - progress);
        score += curvature * (leftover_after_next as f64 - next_item_size as f64).abs();
    }

    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        let next_hardness = next_item_size as f64 / cap_f;
        score += (0.35 + 0.55 * next_hardness) * gap as f64;
        if post_residual > 0 && gap <= 6 {
            score += 6.0;
        }
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
            // dead-space ratio penalty: stranded residual compounds on long streams
