        if next_item_size > 0 && next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            let curvature = 0.08 + 0.04 * (1.0 - horizon);
            score += curvature * (next_post as f64 - next_item_size as f64).abs();
