pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let mut score = post_f;
    let horizon = (remaining / total_items.max(1) as f64).min(1.0);

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the leftover: reward tight two-item packing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        // smooth discount decaying with leftover size (borrowed: strong pull
        // toward near-exhausting residuals after the next placement)
        score -= 55.0 / (1.0 + leftover_after_next as f64 / 10.0);
        score -= (next_item_size as f64).min(post_f) * 0.35;
        // chain lookahead: same item could fit again after the next one
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 12.0;
            }
            // three-step chain potential (deep lookahead when stream is long)
            if leftover_after_next >= 3 * next_item_size {
                score -= 4.0;
                if remaining > 96.0 {
                    score -= 4.0;
                    let four = leftover_after_next - 3 * next_item_size;
                    if four >= next_item_size {
                        score -= 3.0;
                        if four == next_item_size {
                            score -= 5.0;
                        }
                    }
                }
            }
        }
        // exact fill after next item is highly desirable
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0;
        }
        // dead-space: leftover after next is unusably small for next item
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // bonus when residual is a multiple of the next item (perfect tiling)
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        // divisible residuals tile well with many future items
        if post_residual % 25 == 0 {
            score -= 7.0;
        } else if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // pair-coverage coupling: post residual can host next item AND the
        // two-step remainder still exceeds the current item
        if remaining > 48.0 && leftover_after_next >= next_item_size {
            let two_post = leftover_after_next - next_item_size;
            if two_post >= item_size {
                score -= 3.5;
            }
            if two_post == 0 {
                score -= 12.0;
            }
        }
        // consumed-fraction bonus: next item nearly fills the residual
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // two-item lookahead fill ratio: current + next nearly filling the
        // residual is excellent; awkward middles are mildly penalized
        let fill = (item_size + next_item_size) as f64 / post_f.max(1.0);
        if fill > 0.9 && fill <= 1.0 {
            score -= 6.0 * (fill - 0.9) * 10.0;
        }
        // residual-class shaping: prefer residuals that tile into common
        // chunk sizes (borrowed from class-based discounting)
        let class = (post_residual * 8) / bin_capacity;
        score -= 4.0 * class as f64 * horizon;
    }
    // Next item will NOT fit: penalize dead space, worse when it's small.
    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
        if post_residual > 0 && gap <= 6 {
            score += 6.0; // barely-too-small residual is wasted potential
