        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
            // stranded-space compounding penalty on long streams
            if remaining > 64.0 && post_residual >= 8 {
                score += 0.4 * (gap as f64).min(20.0);
                // dead-space ratio penalty: residual that cannot host the next
                // item is likely stranded; penalize proportionally to its size
                // when the stream is long enough that stranded space compounds
                score += 0.06 * post_f * (remaining / 256.0).min(1.0);
