        if remaining < 12.0 {
            score += 55.0;
        }
        // smooth endgame ramp: consolidate residual space before the final phase
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        if remaining < 32.0 {
            score += 0.6 * (32.0 - remaining);
        }
        // large upcoming item with many open bins: fresh bin absorbs it cleanly
        if open_bins_count > 6 && remaining > 200.0 && next_item_size as f64 > 0.6 * cap_f {
