pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tight_fit = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize dead space that cannot fit the average upcoming item.
    let prog = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let expected_next = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
    if (post_residual as f64) < expected_next && post_residual > 0 {
        score += 4.0 * (expected_next - post_residual as f64) * (0.5 + prog);
    }

    // Perfect fit bonus: residual exactly zero.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * prog;
    }

    // Many open bins: prefer consolidating into existing bins (avoid fragmentation).
    score += 0.35 * open_bins_count as f64 * (1.0 - tight_fit);

    // New empty bin candidate: penalize mildly so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - prog);
        // But if no open bin fits well, allow new bin: penalize less when mean residual is low.
        score -= 5.0 * (1.0 - mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    }

    // Prefer bins whose residual deviates from the mean (keeps residual diversity for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - tight_fit);

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 { score -= 15.0; } else { score -= 5.0 * (1.0 - gap as f64 / bin_capacity as f64); }
    } else if next_item_size > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let mut score = post_f;
    let horizon = (remaining / total_items.max(1) as f64).min(1.0);

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the leftover: reward tight two-item packing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        // chain lookahead: same item could fit again after the next one
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 12.0;
            }
            // three-step chain potential (deep lookahead when stream is long)
            if leftover_after_next >= 3 * next_item_size {
                score -= 4.0;
                if remaining > 96.0 {
                    score -= 4.0;
                    let four = leftover_after_next - 3 * next_item_size;
                    if four >= next_item_size {
                        score -= 3.0;
                        if four == next_item_size {
                            score -= 5.0;
                        }
                    }
                }
            }
        }
        // exact fill after next item is highly desirable
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0;
        }
        // dead-space: leftover after next is unusably small for next item
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // bonus when residual is a multiple of the next item (perfect tiling)
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        // divisible residuals tile well with many future items
        if post_residual % 25 == 0 {
            score -= 7.0;
        } else if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // pair-coverage coupling: post residual can host next item AND the
        // two-step remainder still exceeds the current item
        if remaining > 48.0 && leftover_after_next >= next_item_size {
            let two_post = leftover_after_next - next_item_size;
            if two_post >= item_size {
                score -= 3.5;
            }
            if two_post == 0 {
                score -= 12.0;
            } else if two_post <= 6 {
                score -= 8.0;
            }
        }
        // consumed-fraction bonus: next item nearly fills the residual
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // two-item lookahead fill ratio: current + next nearly filling the
        // residual is excellent; awkward middles are mildly penalized
        let fill = (item_size + next_item_size) as f64 / post_f.max(1.0);
        if fill > 0.9 && fill <= 1.0 {
            score -= 6.0 * (fill - 0.9) * 10.0;
        }
        // residual-class shaping: prefer residuals that tile into common
        // chunk sizes (borrowed from class-based discounting)
        let class = (post_residual * 8) / bin_capacity;
        score -= 4.0 * class as f64 * horizon;
        // smooth discount for reusable remainders after the next item
        score -= 5.0 * ((leftover_after_next as f64) / (next_item_size as f64)).min(2.0) * horizon;
        // small clean remainders are excellent staging space
        if leftover_after_next <= 3 {
            score -= 18.0 * (4 - leftover_after_next) as f64;
        } else if leftover_after_next % 10 == 0 {
            score -= 12.0;
        }
        // curvature shaping: prefer post residuals near the next item size
        let curvature = 0.08 + 0.04 * (1.0 - horizon);
        score += curvature * ((leftover_after_next as f64) - (next_item_size as f64)).abs();
        // small-residual sweet spot: residuals of 8-11 fit many small items
        if post_residual >= 8 && post_residual <= 11 {
            score -= 10.0;
        }
    }
    // Next item will NOT fit: penalize dead space, worse when it's small.
    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
        if post_residual > 0 && gap <= 6 {
            score += 6.0; // barely-too-small residual is wasted potential
        }
        // strong dead-space penalty scaled by residual fraction
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
            // stranded-space compounding penalty on long streams
            if remaining > 64.0 && post_residual >= 8 {
                score += 0.4 * (gap as f64).min(20.0);
            }
            // stranded-fraction coupling: unusable fraction of the residual
            // weighted by remaining stream; dead space late is a real loss
            let dead_frac = gap as f64 / next_item_size as f64;
            score += 2.5 * dead_frac * horizon * (1.0 + wf);
            // proportional stranded-space penalty for medium residuals
            if post_residual >= 8 {
                score += 0.06 * post_f * (remaining / 256.0).min(1.0);
