    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - post_f / cap_f);
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving tiny unusable fragments (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    } else if post_residual < 12 {
        score += 20.0 * (12 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    // Progress term: keep flexibility early, prefer closing bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    // NEW-BIN CANDIDATE handling: default unattractive; open only when open
    // bins cannot absorb the item well and stream is long enough to matter.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        // fresh-bin lookahead: open a new bin when remaining stream is long
        // and the only fits would strand residuals smaller than the next item
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - post_f / cap_f);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            if post_f <= 0.10 * cap_f && remaining > 220.0 {
                score -= 12.0;
            }
            if remaining > 96.0 && (next_item_size as f64) > 3.0 * post_f {
                score -= 10.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        // large next item makes a fresh full-capacity bin attractive
        let next_frac = next_item_size as f64 / cap_f;
        if next_frac > 0.5 && remaining > 64.0 {
            score -= 14.0 * (next_frac - 0.5);
        }
        // fresh-bin sizing gate: tiny next item + many open bins => fragmentation
        if next_frac < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        if open_bins_count > 8 && remaining > 128.0 && next_frac < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_frac);
        }
        // fresh-bin rescue for large incoming items with many open bins
        if open_bins_count > 6 && remaining > 200.0 && next_frac > 0.6 {
            score -= 8.0;
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
        // endgame fresh-bin tightening: consolidate before the final phase
        if remaining < 32.0 {
            score += 0.6 * (32.0 - remaining);
        }
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        if remaining < 12.0 {
            score += 55.0;
        }
    } else {
        // existing-bin refinement: penalize residual far above the next item
        // size late in the stream when it cannot be reused soon
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
            score += 5.0;
        }
        // tolerate imperfect fits less when many bins fit (keep tight bins tight)
        if fitting_bins_count > 3 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        // mild quadratic penalty for loose fits when few bins compete
        if fitting_bins_count <= 2 && post_residual > 0 {
            score += 0.05 * (post_f * post_f) / cap_f;
        }
    }

    score
}

