    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: polynomial coupling of post residual with stream progress.
    let mut score = pr as f64 * (1.0 + 0.5 * progress * x) - 0.3 * x * x * (1.0 - progress);

    // Reward tight fits, more strongly later in the stream.
    let tightness = 1.0 - x;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space relative to mean residual across open bins.
    score += 0.2 * (pr as f64 - mean_residual).abs();

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
