        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        // fresh-bin lookahead: open a new bin when remaining stream is long
        // and the only fits would strand residuals smaller than the next item
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - post_f / cap_f);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            if post_f <= 0.10 * cap_f && remaining > 220.0 {
                score -= 12.0;
            }
            if remaining > 96.0 && (next_item_size as f64) > 3.0 * post_f {
                score -= 10.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        // large next item makes a fresh full-capacity bin attractive
        let next_frac = next_item_size as f64 / cap_f;
        if next_frac > 0.5 && remaining > 64.0 {
            score -= 14.0 * (next_frac - 0.5);
        }
        // fresh-bin sizing gate: tiny next item + many open bins => fragmentation
        if next_frac < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        if open_bins_count > 8 && remaining > 128.0 && next_frac < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_frac);
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
        // endgame fresh-bin tightening: consolidate before the final phase
        if remaining < 32.0 {
            score += 0.6 * (32.0 - remaining);
        }
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        if remaining < 12.0 {
            score += 55.0;
        }
    } else {
        // existing-bin refinement: penalize residual far above the next item
        // size late in the stream when it cannot be reused soon
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
            score += 5.0;
        }
        // tolerate imperfect fits less when many bins fit (keep tight bins tight)
        if fitting_bins_count > 3 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        // curvature shaping: prefer post residuals near the next item size,
        // scaled by how much stream remains so late placements tolerate
        // larger leftovers less harshly
        if next_item_size > 0 && next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            let curvature = 0.08 + 0.04 * (1.0 - (remaining / total_items.max(1) as f64).min(1.0));
            score += curvature * (next_post as f64 - next_item_size as f64).abs();
        }
        // mild quadratic penalty for loose fits when few bins compete
        if fitting_bins_count <= 2 && post_residual > 0 {
            score += 0.05 * (post_f * post_f) / cap_f;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by
    // integer division thresholds against capacity fractions.
    let q = post_residual / 10; // residue class in units of 10
    match q {
        0 => score -= 60.0,          // perfect / near-perfect fit
        1 => score -= 25.0,          // tiny dead space, still useful
        2 | 3 => score -= 8.0,       // mid-low class: decent slot
        4 | 5 => score += 5.0,       // half-full leftovers: ambiguous
        6 | 7 => score += 15.0,      // large leftovers: likely splittable later
        _ => score += 25.0,          // mostly-empty bin used wastefully
    }

    // Modulo-3 harmonic coupling between post_residual and next_item_size:
    // if the next item lands exactly into the leftover class, reward it.
    if next_item_size > 0 {
        let r3 = (post_residual % 3) as f64;
        let n3 = (next_item_size % 3) as f64;
        if r3 == n3 {
            score -= 12.0;
        }
        // Next item fits exactly in leftover: strong reward
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves new residue: mild reward scaled by tightness
            let tight = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * tight;
        } else {
            // next item cannot use this bin's leftover: penalize big leftovers
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize opening a new bin when plenty of bins already fit the item
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
        // but allow new bin early in stream or when mean residual is high (fragmented state)
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 15.0 && progress > 0.3 {
            score -= 55.0;
        }
    }

    // Tightness bonus: reward filling large fraction of current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Mean-residual harmonization: bins far below mean residual are better
    // targets (consolidate fragmentation toward the mean).
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Small stream-position modulation for exploration of classes over time
    let phase = ((step_index % 5) as f64) * 1.5;
    score -= phase * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
