pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; anything below a "useful gap" threshold is heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fill: perfect
    } else if post_residual <= 10 {
        // small dead gap: nearly worthless leftover
        score += (12.0 - post_residual as f64) * 8.0;
    } else if post_residual <= 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = item_size as f64 / (item_size + post_residual) as f64;
    score -= tightness * 25.0;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits the post-residual, this placement
    // sets up a chain — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // extra reward if next item fills it nearly exactly
        let gap_after_next = post_residual as f64 - next_item_size as f64;
        if gap_after_next < 10.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        // next item can't use the tiny leftover: penalize creating it
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item is large and current bin's post-fit is poor.
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin
        score = 55.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // next item pairs well in a fresh bin
        }
    }

    // Mild preference for bins below mean residual (consolidating emptier bins)
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
