pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic waste penalty on post-residual, modulated by stream progress.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap * (0.5 + progress);

    // Smooth interaction: residual^3 coupling with progress (late stream -> hate dead space more).
    score += 15.0 * norm_pr.powi(3) * cap * (1.0 + 2.0 * progress);

    // Reward tight fits (small post_residual relative to item size) via smooth logistic-like term.
    let tightness = 1.0 - (pr / (bin_residual.max(1) as f64));
    score -= 20.0 * tightness * tightness * norm_item;

    // Last-chance bonus: smooth, stronger late in the stream.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 12.0 * last_chance * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post-residual (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (-gap / 20.0) * (-gap / 20.0);
        score -= 10.0 * kernel * (1.0 + progress);
    } else {
        // Last item: purely minimize waste.
        score = pr;
    }

    // Mild penalty for spreading across too many open bins, scaled by mean residual alignment.
    let spread = (mean_residual - pr).abs() / cap;
    score += 5.0 * spread * spread;

    // New-bin candidate shaping: empty bin gets a smooth offset that decays with progress,
    // so early stream favors consolidation, late stream tolerates opening bins for tight fits.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 8.0 * (1.0 - progress) * (1.0 - progress) + 3.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let mut score = post_f;

    // Perfect 2-step fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        // chain lookahead
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 12.0;
            }
            if leftover_after_next >= 3 * next_item_size {
                score -= 4.0;
                if remaining > 96.0 {
                    score -= 4.0;
                }
            }
            // three-step exact landing bonus
            let two_post = leftover_after_next - next_item_size;
            if two_post == 0 {
                score -= 30.0;
            } else if two_post <= 6 {
                score -= 14.0;
            } else if two_post >= next_item_size {
                let three_post = two_post - next_item_size;
                if three_post == 0 && remaining > 96.0 {
                    score -= 14.0;
                } else if three_post <= 5 && remaining > 48.0 {
                    score -= 8.0;
                }
                // pair-coverage: current item also fits after next two
                if three_post >= item_size {
                    score -= 3.5;
                }
            }
            // reusable remainder depth bonus
            score -= 5.0 * (leftover_after_next as f64 / next_item_size as f64).min(2.0);
        }
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0 - 4.0 * leftover_after_next as f64;
        } else if leftover_after_next <= 8 {
            score -= 14.0;
        }
        // small reusable remainder that fits either current or next item
        if leftover_after_next > 0 && leftover_after_next <= 10 && leftover_after_next >= item_size.min(next_item_size) {
            score -= 4.0;
        }
        // dead-space check
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // multiple-of-next tiling bonus
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        if leftover_after_next > 0 && leftover_after_next % 10 == 0 {
            score -= 28.0;
        }
        // reward absorbing a big chunk of the next item size
        score -= (next_item_size as f64).min(post_f) * 0.35;
        // consumed-fraction bonus: nearly-emptying the bin with next item
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // two-item lookahead fill ratio: reward near-exact two-item fills
        if leftover_after_next > 0 {
            let fill = (item_size + next_item_size) as f64 / post_f;
            if fill > 0.9 && fill <= 1.0 {
                score -= 6.0 * (fill - 0.9) * 10.0;
            }
            if leftover_after_next < 4 {
                score += 3.0;
            }
        }
        // curvature: keep post residuals near the next item size slightly preferred,
        // scaled by remaining stream so late placements tolerate leftovers
        let curvature = 0.08 + 0.04 * (1.0 - (remaining / total_items.max(1) as f64).min(1.0));
        score += curvature * (leftover_after_next as f64 - next_item_size as f64).abs();
    }

    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        let next_hardness = next_item_size as f64 / cap_f;
        score += (0.35 + 0.55 * next_hardness) * gap as f64;
        if post_residual > 0 && gap <= 6 {
            score += 6.0;
        }
        if post_residual > 0 {
            let wf = post_f / cap_f;
