            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        // Endgame guard: prefer filling existing bins near the end.
        if remaining < 12.0 {
            score += 55.0;
        }
        // extended endgame ramp: consolidate before final phase
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    // Residuals divisible by small common item sizes (10..80) are more reusable.
    let mut reuse_bonus = 0.0;
    for d in [10u32, 20, 25, 40, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            reuse_bonus += 4.0 + (post_residual as f64) / (d as f64);
        }
    }
    score -= reuse_bonus;

    // Integer-division threshold: how many "average" items fit in post_residual
    let avg_item = 40u32;
    let fits_count = post_residual / avg_item;
    score -= fits_count as f64 * 6.0;

    // Lookahead coupling: can next_item_size fit exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // partial credit, scaled by tightness of fit
            let tight = (post_residual - next_item_size) as f64;
            score -= 60.0 - tight * 0.5;
        } else {
            // next item cannot fit here: penalize proportionally to wasted harmonic class
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
            // penalize residuals in "dead" classes (small, unusable slivers)
            if post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: discourage opening new bins unless current bin is bad
    if bin_residual == bin_capacity {
        score += 250.0;
        // allow new bin late in stream if open bins are crowded
        if post_residual == bin_capacity && (open_bins_count as f64) > mean_residual / 10.0 {
            score += 100.0;
        }
    }

    // Prefer tighter (fuller) bins: reward low residual fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 30.0;

    // Stream progression: as stream ends, be greedier about filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;
    if post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    // Mean residual coupling: if mean residual is large, prefer consolidating
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

