    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a future
    // item (min item size 1) are already counted by the base term; residuals
    // that cannot fit the lookahead item are extra-wasteful.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize "awkward" residuals: small but not zero gaps are dead space.
    if post_residual > 0 && post_residual <= 15 {
        score += 20.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // opening a new bin is cheap so don't overload tight bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are congested
        // or the fit here would create big dead space.
        score += 8.0 + pressure * 2.0;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        score += pressure * 0.5;
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps bin states balanced).
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

