pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the residual after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable leftovers.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste.min(40.0);
    }

    // Compare post_residual to mean residual: leaving near-mean residual keeps flexibility.
    let dev = post_residual as f64 - mean_residual;
    score += 0.12 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Avoid fragmenting many open bins when few fit.
    if fitting_bins_count > 1 && post_residual < 10 {
        score += 8.0;
    }

    // Late in the stream, tighten packing: penalize large leftovers harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.10;

    // New-bin candidate: only attractive when current bin would leave tiny waste
    // or nothing fits well; make empty bin moderately costly by default.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let horizon = (remaining / total_items.max(1) as f64).min(1.0);
    let mut score = post_f;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the leftover: reward tight two-item packing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        // chain lookahead: same item could fit again after the next one
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 12.0;
            }
            // three-step chain potential (deep lookahead when stream is long)
            if leftover_after_next >= 3 * next_item_size {
                score -= 4.0;
                if remaining > 96.0 {
                    score -= 4.0;
                    let four = leftover_after_next - 3 * next_item_size;
                    if four >= next_item_size {
                        score -= 3.0;
                        if four == next_item_size {
                            score -= 5.0;
                        }
                    }
                }
            }
        }
        // exact fill after next item is highly desirable
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0;
        }
        // dead-space: leftover after next is unusably small for next item
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // bonus when residual is a multiple of the next item (perfect tiling)
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        // divisible residuals tile well with many future items
        if post_residual % 25 == 0 {
            score -= 7.0;
        } else if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // pair-coverage coupling: post residual can host next item AND the
        // two-step remainder still exceeds the current item
        if remaining > 48.0 && leftover_after_next >= next_item_size {
            let two_post = leftover_after_next - next_item_size;
            if two_post >= item_size {
                score -= 3.5;
            }
            if two_post == 0 {
                score -= 12.0;
            } else if two_post <= 6 {
                score -= 8.0;
            }
        }
        // consumed-fraction bonus: next item nearly fills the residual
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // two-item lookahead fill ratio
        let fill = (item_size + next_item_size) as f64 / post_f.max(1.0);
        if fill > 0.9 && fill <= 1.0 {
            score -= 6.0 * (fill - 0.9) * 10.0;
        }
        // residual-class shaping (borrowed from best: stronger class discount)
        let class = (post_residual * 8) / bin_capacity;
        score -= (4.0 + 8.0 * horizon) * class as f64;
        // smooth discount for reusable remainders after the next item
        score -= 5.0 * ((leftover_after_next as f64) / (next_item_size as f64)).min(2.0) * horizon;
        // small clean remainders are excellent staging space
        if leftover_after_next <= 3 {
            score -= 18.0 * (4 - leftover_after_next) as f64;
        } else if leftover_after_next % 10 == 0 {
            score -= 12.0;
        }
        // curvature shaping: prefer post residuals near the next item size
        let curvature = 0.08 + 0.04 * (1.0 - horizon);
        score += curvature * ((leftover_after_next as f64) - (next_item_size as f64)).abs();
        // small-residual sweet spot: residuals of 8-11 fit many small items
        if post_residual >= 8 && post_residual <= 11 {
            score -= 10.0;
        }
        // combined: reusable remainder bonus scaled by stream depth (from best)
        if leftover_after_next > 0 && leftover_after_next >= next_item_size {
            score -= 5.0 * ((leftover_after_next as f64) / (next_item_size as f64)).min(2.0);
        }
        // combined: mid-range leftover that can host min(item, next) (from best)
        if leftover_after_next > 0 && leftover_after_next <= 10 && leftover_after_next >= item_size.min(next_item_size) {
            score -= 4.0;
        }
    }
    // Next item will NOT fit: penalize dead space, worse when it's small.
    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
        if post_residual > 0 && gap <= 6 {
            score += 6.0; // barely-too-small residual is wasted potential
        }
        // strong dead-space penalty scaled by residual fraction
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
            // stranded-space compounding penalty on long streams
            if remaining > 64.0 && post_residual >= 8 {
                score += 0.4 * (gap as f64).min(20.0);
            }
            // stranded-fraction coupling
            let dead_frac = gap as f64 / next_item_size as f64;
            score += 2.5 * dead_frac * horizon * (1.0 + wf);
