            if post_residual >= 8 {
                score += 0.06 * post_f * (remaining / 256.0).min(1.0);
            }
        }
    }

    // Reward bins tighter than the mean residual (good fill), punish loose ones.
    score -= (mean_residual - post_f) * 0.5;

    // Reward tightness of the actual placement relative to bin residual.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Quadratic residual fraction: strong pull toward full bins.
    score += 32.0 * (post_f / cap_f) * (post_f / cap_f);

    // Last-chance bin: use it when the fit is tight.
    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - post_f / cap_f);
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving tiny unusable fragments (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    } else if post_residual < 12 {
        score += 20.0 * (12 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    // Progress term: keep flexibility early, prefer closing bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    // NEW-BIN CANDIDATE handling: default unattractive; open only when open
    // bins cannot absorb the item well and stream is long enough to matter.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        // fresh-bin lookahead: open a new bin when remaining stream is long
        // and the only fits would strand residuals smaller than the next item
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - post_f / cap_f);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            if post_f <= 0.10 * cap_f && remaining > 220.0 {
                score -= 12.0;
            }
            if remaining > 96.0 && (next_item_size as f64) > 3.0 * post_f {
                score -= 10.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        // large next item makes a fresh full-capacity bin attractive
        let next_frac = next_item_size as f64 / cap_f;
        if next_frac > 0.5 && remaining > 64.0 {
            score -= 14.0 * (next_frac - 0.5);
        }
        // fresh-bin sizing gate: tiny next item + many open bins => fragmentation
        if next_frac < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        if open_bins_count > 8 && remaining > 128.0 && next_frac < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_frac);
        }
        // fresh-bin rescue for large incoming items with many open bins
        if open_bins_count > 6 && remaining > 200.0 && next_frac > 0.6 {
            score -= 8.0;
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
        // endgame fresh-bin tightening: consolidate before the final phase
        if remaining < 32.0 {
            score += 0.6 * (32.0 - remaining);
        }
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        if remaining < 12.0 {
            score += 55.0;
        }
        // combined: large next item + no fitting bin => strongly prefer fresh
        if next_item_size > post_residual && next_frac > 0.35 && fitting_bins_count == 0 {
            score -= 90.0 * horizon;
        }
    } else {
        // existing-bin refinement: penalize residual far above the next item
        // size late in the stream when it cannot be reused soon
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
            score += 5.0;
        }
        // tolerate imperfect fits less when many bins fit (keep tight bins tight)
        if fitting_bins_count > 3 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        // mild quadratic penalty for loose fits when few bins compete
        if fitting_bins_count <= 2 && post_residual > 0 {
            score += 0.05 * (post_f * post_f) / cap_f;
        }
        // combined: near-miss gap penalty — residual just below next item is
        // the worst kind of dead space; scale with how close it is
        if next_item_size > post_residual && post_residual > 0 {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 12.0 {
                score += (12.0 - gap) * 1.2 * horizon;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins that end with small post-residual.
    let fit_quality = (post_residual as f64) / (bin_capacity as f64);
    score += fit_quality * fit_quality * 40.0;

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item then fits almost exactly.
            let post2 = post_residual - next_item_size;
            if post2 < 10 {
                score -= 6.0;
            }
        } else {
            // Post-residual too small for the next item: mild penalty proportional to waste.
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.4;
        }
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins
    // (consolidation), penalize opening new bins implicitly.
    if open_bins_count > 2 {
        let consolidation = mean_residual / (bin_capacity as f64);
        score -= consolidation * 4.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (future flexibility); later, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0;

    // New-bin candidate handling: opening a fresh bin is attractive early or when
    // the item is large and no open bin fits well; otherwise discourage it.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        let poor_alternatives = fitting_bins_count == 0 || (post_residual as f64) < 0.25 * (bin_capacity as f64);
        if large_item || poor_alternatives || progress < 0.2 {
            score -= 25.0;
        } else {
            score += 18.0;
        }
    }

    // Mild preference for fuller existing bins (larger item_size relative to residual).
    let fill_ratio = (item_size as f64) / (bin_residual as f64);
    score -= fill_ratio * 5.0;

    // Small tie-breaker against proliferation of barely-used bins.
    score += open_bins_count as f64 * 0.05;

    score
}

