    let mut score = prn.powf(1.6) * cap;

    // Smooth non-linear coupling with stream progress: waste is more costly later
    score *= 1.0 + 1.2 * progress * prn;

    // Polynomial penalty for dead space that can never be used well
    let dead = if prn > 0.0 { prn * prn * (1.0 - prn) } else { 0.0 };
    score += dead * cap * (0.5 + 0.5 * progress);

