pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse buckets.
    // Small leftovers (<10) are dead space -> penalize via squaring effect.
    let pr = post_residual as f64;
    if post_residual < 10 {
        score += 60.0 - 2.0 * pr; // near-zero leftover is great, but <10 class penalized less at 0
