        // mid-stream fresh-bin damping
        if bin_residual == bin_capacity && open_bins_count > 8 && remaining > 128.0 && next_hardness < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_hardness);
        }
    }

    // Reward bins tighter than the mean residual.
    score -= (mean_residual - post_f) * 0.5;

    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Quadratic fullness pull plus residual-class term.
    let wf = post_f / cap_f;
    score += 32.0 * wf * wf;
    let class = (post_residual * 8) / bin_capacity;
    score -= 12.0 * class as f64;

    // Fine-grained small-residual shaping.
    if post_residual > 0 {
        if post_residual < 8 {
            score -= 35.0;
        } else if post_residual < 12 {
            score += 45.0 * (12 - post_residual) as f64;
        } else if post_residual <= 20 {
            score += 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 7.0;
        }
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // stranded-near-miss shaping
        if next_item_size > post_residual && post_residual >= 8 && post_residual < next_item_size {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - wf);
    } else if fitting_bins_count >= 2 && fitting_bins_count <= 3 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Many fitting bins: keep tight bins tight.
    if fitting_bins_count > 3 && bin_residual < bin_capacity && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mild quadratic residual pressure when few bins compete.
    if fitting_bins_count <= 2 && post_residual > 0 {
        score += 0.05 * (post_f * post_f) / cap_f;
    }

    // Late-stream reuse penalty.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
        score += 5.0;
    }

    // Progress term.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    // NEW-BIN CANDIDATE handling.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - wf);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            // large next item with many open bins: fresh bin absorbs it well
            if open_bins_count > 6 && remaining > 200.0 && next_item_size as f64 > 0.6 * cap_f {
                score -= 8.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        // Endgame guard: prefer filling existing bins near the end.
        if remaining < 12.0 {
            score += 55.0;
        }
        // extended endgame ramp
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        // fresh-bin utility gate: only open a new bin early when future
        // demand is likely to fill it; late in stream prefer existing slack
        let expected_future = remaining * (mean_residual / cap_f).max(0.15);
        if expected_future < 0.5 * cap_f && open_bins_count > 3 {
            score += 7.0 * (1.0 - expected_future / (0.5 * cap_f));
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Mid-range gaps that only fit the smallest items are also dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open,
    // but allow opening a new bin when few are open.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good fit,
        // so we only open when existing fits are poor.
        score += 25.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual exactly, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mean residual coupling: bins with residual far below mean are already tight;
    // filling them is good (keeps mean spread controlled).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    }

    score
}

