pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect match for next item: strongly reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward proportional to closeness.
            let gap = post_residual as f64 - nxt;
            score -= 20.0 / (1.0 + gap / 20.0);
        } else {
            // Next item won't fit: penalize leftover dead space below next item size.
            score += 10.0 + (nxt - post_residual as f64) * 0.3;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Penalize creating tiny unusable fragments (< 10, the min item size historically).
    if post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins that are tighter than average when fit is good,
    // but avoid dumping into nearly-empty bins when many bins are open.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // (avoids opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when no good fit exists
    // (e.g., when mean residual is low and current fit would waste a lot).
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 20.0 - waste_penalty * 15.0 - mean_residual * 0.1;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
