                let tiles = (leftover_after_next / next_item_size) as f64;
                if tiles >= 2.0 {
                    score -= 3.0 * (tiles - 2.0).min(3.0);
                }
            }
        }
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
