    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    } else if post_residual < 12 {
        score += 20.0 * (12 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    // Progress term: keep flexibility early, prefer closing bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    // GEN34: residual-reusability shaping with sharper cliff near exact reuse
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 4 {
            score -= 7.5 * (5.0 - slack as f64) * (0.5 + horizon);
        } else if slack < next_item_size {
            score += 2.5 * (slack as f64 / next_item_size as f64) * (0.5 + horizon);
        }
    }
    // GEN34: prefer residuals matching common small-item sizes on long streams
    if next_item_size > 0 && post_residual > 0 && remaining > 64.0 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
        score -= 3.0;
    }

    // NEW-BIN CANDIDATE handling: default unattractive; open only when open
    // bins cannot absorb the item well and stream is long enough to matter.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
