        }
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // common small-item sizes ease future fits
        if remaining > 64.0 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 3.0;
        }
