pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, waste is cheap; later, dead space is penalized quadratically.
    let mut score = pr * (1.0 + 3.0 * progress * norm_pr);

    // Cubic smooth term: large residuals late in stream are heavily penalized.
