    // Tight fit reward: subtract for small post_residual, scaled by progress.
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * (0.5 + 0.5 * progress);

    // Lookahead: reward bins whose post-residual matches next item size.
    if next_item_size > 0 {
        let match_term = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 6.0 * match_term * (1.0 - progress);
    }

    // Last-chance bin: strong bonus to avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding penalty: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * norm_pr;

    // Mean residual alignment: bins far from mean residual get slight penalty.
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    // New-bin candidate: make empty bins moderately attractive only when
    // residuals across open bins are low and item is large.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (0.6 + 0.4 * progress) - 10.0 * avg_fill - item_size as f64 * 0.3;
    }

    score
}

