    // Reward if the lookahead item fits exactly into post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained closure
        } else if next_item_size <= post_residual {
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 25.0 - chain_fit * 0.3; // tighter chain fit rewarded more
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2; // next item won't chain
        }
    } else {
        // Last item: closing a bin fully is ideal.
        score -= (cap - post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless they waste space.
        score = cap * 0.75
            + (open_bins_count as f64) * 2.0
            + mean_residual * 0.1;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin pairs well with upcoming large item
        }
        if fitting_bins_count == 0 {
            score -= cap; // forced new bin
        }
    } else {
        // Fraction-of-capacity harmonic: residual in (0, cap/4] is good closure.
        let quarter = cap / 4.0;
        let pr = post_residual as f64;
        if pr <= quarter && pr > 0.0 {
            score -= 10.0;
        }
        // Penalize opening waste when many bins already fit the item.
        if fitting_bins_count > 3 {
            score += (fitting_bins_count as f64 - 3.0) * 2.0;
        }
    }

    // Stream progression: early on, be conservative (prefer tight fits);
    // late, prefer closing bins to reduce open-bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let horizon = (remaining / (total_items as f64).max(1.0)).min(1.0);
    let mut score = post_f;

    // Perfect 2-step fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
