        if next_item_size as f64 > 0.5 * cap_f && fitting_bins_count <= 2 && remaining > 32.0 {
            score -= 9.0 * (next_item_size as f64 / cap_f);
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
    }

    score
}

