            let slack_after_next = post_residual - next_item_size;
            score += slack_after_next as f64 * 0.5;
        } else {
            // next item won't fit here; mild bonus for leaving larger residual
            score -= 20.0;
        }
    }

    // Compare residual against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize tiny unusable dead space (waste zones)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when existing bins are tight
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        // If open bins are quite full on average, opening new bin is reasonable
        score += 80.0 * (1.0 - avg_tightness);
        // Avoid hoarding bins early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive
        if next_item_size > 0 && next_item_size > item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let horizon = (remaining / (total_items as f64).max(1.0)).min(1.0);
    let mut score = post_f;

    // Perfect 2-step fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        // chain lookahead
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 12.0;
            }
            if leftover_after_next >= 3 * next_item_size {
                score -= 4.0;
                if remaining > 96.0 {
                    score -= 4.0;
                }
            }
            // three-step exact landing bonus
            let two_post = leftover_after_next - next_item_size;
            if two_post == 0 {
                score -= 30.0;
            } else if two_post <= 6 {
                score -= 14.0;
            } else if two_post >= next_item_size {
                let three_post = two_post - next_item_size;
                if three_post == 0 && remaining > 96.0 {
                    score -= 14.0;
                } else if three_post <= 5 && remaining > 48.0 {
                    score -= 8.0;
                }
                // pair-coverage: current item also fits after next two
                if three_post >= item_size {
                    score -= 3.5;
                }
            }
            // chained reuse reward, stronger late in stream
            if post_residual >= 2 * next_item_size + item_size && remaining > 24.0 {
                score -= 10.0 * horizon;
            }
        }
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0 - 4.0 * leftover_after_next as f64;
        } else if leftover_after_next <= 8 {
            score -= 14.0;
        }
        // small reusable remainder that fits either current or next item
        if leftover_after_next > 0 && leftover_after_next <= 10 && leftover_after_next >= item_size.min(next_item_size) {
            score -= 4.0;
        }
        // dead-space check
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // multiple-of-next tiling bonus
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        // reward absorbing a big chunk of the next item size
        score -= (next_item_size as f64).min(post_f) * 0.35;
        // consumed-fraction bonus: nearly-emptying the bin with next item
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // curvature: keep post residuals near the next item size slightly preferred
        let curvature = 0.08 + 0.04 * (1.0 - horizon);
        score += curvature * (leftover_after_next as f64 - next_item_size as f64).abs();
        // extra reuse reward scaled by leftover/next ratio
        if leftover_after_next > 0 {
            score -= 5.0 * ((leftover_after_next as f64) / (next_item_size as f64)).min(2.0);
        }
        // (item+next) fill shaping: prefer near-complete two-item fills
        let fill = (item_size + next_item_size) as f64 / post_f;
        if fill > 0.9 && fill <= 1.0 {
            score -= 6.0 * (fill - 0.9) * 10.0;
        }
    }

    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        let next_hardness = next_item_size as f64 / cap_f;
        score += (0.35 + 0.55 * next_hardness) * gap as f64;
        if post_residual > 0 && gap <= 6 {
            score += 6.0;
        }
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
            // dead-space compounding penalty scaled by fragmentation
            let frag = (open_bins_count as f64 / 16.0).min(1.0);
            if remaining > 32.0 {
                score += 1.1 * gap as f64 * frag * (remaining / 512.0).min(1.0);
            }
            // dead-fraction penalty with horizon
            let dead_frac = gap as f64 / (next_item_size as f64);
            score += 2.5 * dead_frac * horizon * (1.0 + post_f / cap_f);
            // GEN33-style: penalize near-misses harder when horizon is long
            if post_residual >= item_size && gap <= 6 {
                score += (7.0 - gap as f64) * 2.2 * (0.4 + horizon);
            }
        }
        // moderate stranded residual on a very long stream: fresh bin preferred
        if bin_residual == bin_capacity && post_f <= 0.10 * cap_f && remaining > 220.0 {
            score -= 12.0;
        }
        // fresh-bin sizing gate: tiny next item + many open bins -> keep fresh bin closed
        if bin_residual == bin_capacity && next_hardness < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        // mid-stream fresh-bin damping
        if bin_residual == bin_capacity && open_bins_count > 8 && remaining > 128.0 && next_hardness < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_hardness);
        }
        if bin_residual == bin_capacity && next_item_size > bin_residual {
            score -= 90.0;
        }
    }

    // Reward bins tighter than the mean residual.
    score -= (mean_residual - post_f) * 0.5;

    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Quadratic fullness pull plus residual-class term.
    let wf = post_f / cap_f;
    score += 32.0 * wf * wf;
    let class = (post_residual * 8) / bin_capacity;
    score -= 12.0 * class as f64;

    // Fine-grained small-residual shaping.
    if post_residual > 0 {
        if post_residual < 8 {
            score -= 35.0;
        } else if post_residual < 12 {
            score += 45.0 * (12 - post_residual) as f64;
        } else if post_residual <= 20 {
            score += 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 7.0;
        }
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // stranded-near-miss shaping
        if next_item_size > post_residual && post_residual >= 8 && post_residual < next_item_size {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
        // prefer residuals matching common small-item sizes when many items remain
        if remaining > 64.0 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
            score -= 3.0;
        }
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - wf);
    } else if fitting_bins_count >= 2 && fitting_bins_count <= 3 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
