    if fitting_bins_count <= 2 && post_residual > 0 {
        score += 0.05 * (post_f * post_f) / cap_f;
    }

    // residual-reusability shaping: sharper cliff near exact reuse
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
