        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - wf);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            // large next item with many open bins: fresh bin absorbs it well
            if open_bins_count > 6 && remaining > 200.0 && next_item_size as f64 > 0.6 * cap_f {
                score -= 8.0;
            }
            // large next item with few hosts: fresh bin preserves contiguous space
            if next_item_size as f64 > 0.5 * cap_f && fitting_bins_count <= 2 && remaining > 32.0 {
                score -= 9.0 * (next_item_size as f64 / cap_f);
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        // Endgame guard: prefer filling existing bins near the end.
        if remaining < 12.0 {
            score += 55.0;
        }
        // extended endgame ramp: consolidate before final phase
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
        // fresh-bin utility gate based on expected future residual demand
        let expected_future = remaining * (mean_residual / cap_f).max(0.15);
        if expected_future < 0.5 * cap_f && open_bins_count > 3 {
            score += 7.0 * (1.0 - expected_future / (0.5 * cap_f));
        }
        if next_item_size as f64 > 0.85 * cap_f && remaining > 96.0 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for minimal post-residual (tight fit).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer bins already below mean residual (consolidate emptier bins? no —
    // prefer bins with residual close to mean to keep balance, slight pull).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // Lookahead: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item does NOT fit in post-residual but would fit an emptier bin,
    // slight penalty for wasting capacity that the lookahead needs.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // New-bin candidate logic: only attractive when no open bin fits well
    // or when open bins are crowded.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin early in the stream (more future to use it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
        // Cheaper when few open bins exist.
        score -= (open_bins_count.min(20) as f64).recip() * 10.0;
        // Expensive when many bins could fit the item (avoid unnecessary bins).
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If the next item is large and this item is small, a fresh bin keeps
        // flexibility for pairing.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 15.0;
        }
        // If this bin would be the last chance, opening new bin is bad.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
    }

    // Late in stream: avoid opening new bins, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.85 {
        score += (bin_residual == bin_capacity) as u32 as f64 * 40.0;
        score -= 5.0 * progress;
    }

    // Mild penalty scaling with how full the bin already is, encouraging
    // distributing items across bins only when residuals are similar.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += fill * fill * 8.0;

    score
}

