let expected_future = remaining * (mean_residual / cap_f).max(0.15) ; if expected_future < 0.5 * cap_f && open_bins_count > 3 { score += 7.0 * (1.0 - expected_future / (0.5 * cap_f)) ; } if next_item_size as f64 > 0.85 * cap_f && remaining > 96.0 { score -= 6.0 ; } // GEN33: preserve large contiguous residuals for large upcoming items
if next_item_size as f64 > 0.5 * cap_f && fitting_bins_count <= 2 && remaining > 32.0 { score -= 9.0 * (next_item_size as f64 / cap_f) ; } // GEN38: a fresh bin is most valuable when it can host the next item
