pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range gaps (10..25) can only host the smallest items: moderate penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty amplified when the leftover can't fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Open-bins pressure: with many open bins, prefer consolidating into tight fits
    // (penalize bins that leave lots of slack when bin count is high).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * (open_bins_count as f64) * (post_residual as f64) / 100.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the current bin's fit is poor
    // (large post_residual relative to capacity) or the gap blocks the next item.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.6 * (bin_capacity as f64);
        let blocks_next = next_item_size > 0 && (bin_residual - item_size) < next_item_size && (bin_residual - item_size) < 10;
        if poor_fit || blocks_next {
            score -= 40.0;
        } else {
            score += 30.0; // keep using open bins when fit is decent
        }
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to the mean (avoid extreme outliers).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

