            score -= 14.0 * (next_frac - 0.5);
        }
        if next_frac > 0.5 && fitting_bins_count <= 2 && remaining > 32.0 {
            score -= 10.0 * next_frac;
        }
        if next_frac < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        if open_bins_count > 8 && remaining > 128.0 && next_frac < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_frac);
        }
        if open_bins_count > 6 && remaining > 200.0 && next_frac > 0.6 {
            score -= 8.0;
        }
        if next_frac > 0.85 && remaining > 96.0 {
            score -= 6.0;
        }
        // GEN44: fragmentation-driven fresh-bin pull for medium next items
        if open_bins_count > 10 && next_frac > 0.35 && remaining > 96.0 && next_item_size > post_residual {
            score -= 5.0;
        }
        // discourage fresh bin when an open bin achieves exact-fit with next item
        if next_item_size > 0 && post_residual == next_item_size && remaining > 16.0 {
            score += 45.0;
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
        if remaining < 32.0 {
            score += 0.6 * (32.0 - remaining);
        }
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        if remaining < 12.0 {
            score += 55.0;
        }
        let expected_future = remaining * (mean_residual / cap_f).max(0.15);
        if expected_future < 0.5 * cap_f && open_bins_count > 3 {
            score += 7.0 * (1.0 - expected_future / (0.5 * cap_f));
        }
    } else {
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
            score += 5.0;
        }
        if fitting_bins_count > 3 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score += 0.05 * (post_f * post_f) / cap_f;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills of the current bin.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Exact match for the next item is the dream outcome.
        if gap == 0.0 {
            score -= 800.0;
        } else if gap <= 10.0 {
            score -= 300.0 - gap * 20.0;
        } else {
            score -= 100.0 / gap;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how badly it misses,
        // unless post_residual is tiny (dead space anyway).
        let miss = (next_item_size - post_residual) as f64;
        if post_residual > 0 {
            score += miss * 0.5;
        }
    }

    // Penalize large leftover dead space relative to mean residual of open bins.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Mild pressure to prefer existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as more bins are open / stream progresses.
        score += 40.0 + 60.0 * progress + (open_bins_count as f64) * 2.0;
        // But allow a new bin if the current item leaves a large residual that no
        // lookahead can use (avoid fragmenting existing bins with bad fits).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), superlinear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus scaled by how snugly the next item fits the leftover.
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 8.0;
        } else {
            // Penalize leaving a residual just below the next item (wasted dead space).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 && gap <= 10.0 {
                score += gap * 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: default penalty; only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let mut penalty = 45.0;
        if fitting_bins_count > 0 {
            // Compare best achievable residual among fitting bins via mean residual.
            let avg_post = (mean_residual - item_size as f64).max(0.0);
            penalty += avg_post * 0.8;
        }
        // Late in the stream, opening bins is more costly (fewer future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += progress * 25.0;
        // Many open bins already: discourage spreading.
        penalty += open_bins_count as f64 * 2.0;
        score += penalty;
    }

    // Mild reward for placing into bins with large residual relative to the mean
    // (balances load, keeps small residuals from multiplying).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, tolerate larger residuals; late in the stream, penalize them heavily.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 30.0 * poly;

    // Perfect fit reward (smooth via cubic falloff).
    let fit_tightness = 1.0 - (pr / cap);
    score -= 25.0 * fit_tightness * fit_tightness * fit_tightness;

    // Lookahead coupling: reward leaving space usable by the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // Next item won't fit in this residual: penalize proportionally to waste.
            let waste = (nx - pr) / cap;
            score += 15.0 * waste * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly early, more strongly late (prefer consolidation),
    // but allow it when residual would be an awkward dead space.
    if bin_residual == bin_capacity {
        let dead = (pr as f64 / cap).min(1.0);
        score += 8.0 + 25.0 * progress - 10.0 * dead * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (keep residuals balanced).
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let mut score = post_f;
    let horizon = (remaining / total_items.max(1) as f64).min(1.0);

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
