        // bonus when residual is a multiple of the next item (perfect tiling)
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        if post_residual % 25 == 0 {
            score -= 7.0;
        } else if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // pair-coverage coupling
        if remaining > 48.0 && leftover_after_next >= next_item_size {
            let two_post = leftover_after_next - next_item_size;
            if two_post >= item_size {
                score -= 3.5;
            }
            if two_post == 0 {
                score -= 12.0;
            } else if two_post <= 6 {
                score -= 8.0;
            }
        }
        // consumed-fraction bonus: next item nearly fills the residual
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // two-item lookahead fill ratio
        let fill = (item_size + next_item_size) as f64 / post_f.max(1.0);
        if fill > 0.9 && fill <= 1.0 {
            score -= 6.0 * (fill - 0.9) * 10.0;
        }
        // residual-class shaping
        let class = (post_residual * 8) / bin_capacity;
        score -= 4.0 * class as f64 * horizon;
        score -= 7.0 * ((leftover_after_next as f64) / (next_item_size as f64)).min(2.0) * horizon;
        // small clean remainders are excellent staging space
        if leftover_after_next <= 3 {
            score -= 18.0 * (4 - leftover_after_next) as f64;
        } else if leftover_after_next % 10 == 0 {
            score -= 12.0;
        }
        // curvature shaping: prefer post residuals near the next item size
        let curvature = 0.08 + 0.04 * (1.0 - horizon);
        score += curvature * ((leftover_after_next as f64) - (next_item_size as f64)).abs();
        // small-residual sweet spot: residuals of 8-11 fit many small items
        if post_residual >= 8 && post_residual <= 11 {
            score -= 10.0;
        }
        if post_residual >= 12 && post_residual <= 20 {
            score -= 6.0;
        }
        // chained reuse reward
        if post_residual >= 2 * next_item_size + item_size && remaining > 24.0 {
            score -= 10.0 * horizon;
        }
        // GEN45: reward residuals that can host the next item twice (two-step lookahead)
        if post_residual >= 2 * next_item_size && remaining > 32.0 {
            let two_slack = post_residual - 2 * next_item_size;
            if two_slack == 0 {
                score -= 10.0 * (0.5 + horizon);
            } else if two_slack <= 6 {
                score -= 4.5 * (0.5 + horizon);
            }
        }
        // GEN45: three-step lookahead for large residuals late in stream
        if post_residual >= 3 * next_item_size && remaining > 96.0 {
            score -= 5.0 * horizon;
        }
    }
    // Next item will NOT fit: penalize dead space, worse when it's small.
    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
        if post_residual > 0 && gap <= 6 {
            score += 6.0;
        }
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
            if remaining > 64.0 && post_residual >= 8 {
                score += 0.4 * (gap as f64).min(20.0);
            }
            let dead_frac = gap as f64 / next_item_size as f64;
            score += 2.5 * dead_frac * horizon * (1.0 + wf);
            if post_residual >= 8 {
                score += 0.06 * post_f * (remaining / 256.0).min(1.0);
            }
            if remaining > 32.0 {
                let frag = (open_bins_count as f64 / 16.0).min(1.0);
                score += 1.1 * gap as f64 * frag * (remaining / 512.0).min(1.0);
            }
            if post_residual >= item_size && gap <= 6 {
                score += (7.0 - gap as f64) * 2.2 * (0.4 + horizon);
            }
            // GEN45: sharper near-miss penalty — the main dead-space source
            if gap <= 10 {
                score += (10.5 - gap as f64) * 2.4 * (0.4 + horizon);
            }
        }
    }

    // Reward bins tighter than the mean residual (good fill), punish loose ones.
    score -= (mean_residual - post_f) * 0.5;

    // Reward tightness of the actual placement relative to bin residual.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Quadratic residual fraction: strong pull toward full bins.
    score += 32.0 * (post_f / cap_f) * (post_f / cap_f);

    // Last-chance bin: use it when the fit is tight.
    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - post_f / cap_f);
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving tiny unusable fragments (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    } else if post_residual < 12 {
        score += 20.0 * (12 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    // Progress term: keep flexibility early, prefer closing bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    // residual-reusability shaping with sharper cliff near exact reuse
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 4 {
            score -= 7.5 * (5.0 - slack as f64) * (0.5 + horizon);
        } else if slack < next_item_size {
            score += 2.5 * (slack as f64 / next_item_size as f64) * (0.5 + horizon);
        }
    }
    // prefer residuals matching common small-item sizes on long streams
    if next_item_size > 0 && post_residual > 0 && remaining > 64.0 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
        score -= 3.0;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        // fresh-bin lookahead
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - post_f / cap_f);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            if post_f <= 0.10 * cap_f && remaining > 220.0 {
                score -= 12.0;
            }
            if remaining > 96.0 && (next_item_size as f64) > 3.0 * post_f {
                score -= 10.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        let next_frac = next_item_size as f64 / cap_f;
        if next_frac > 0.5 && remaining > 64.0 {
            score -= 14.0 * (next_frac - 0.5);
        }
        if next_frac > 0.5 && fitting_bins_count <= 2 && remaining > 32.0 {
            score -= 9.0 * next_frac;
        }
        if next_frac < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        if open_bins_count > 8 && remaining > 128.0 && next_frac < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_frac);
        }
        if open_bins_count > 6 && remaining > 200.0 && next_frac > 0.6 {
            score -= 8.0;
        }
        if next_frac > 0.85 && remaining > 96.0 {
            score -= 6.0;
        }
        // GEN45: discourage opening a fresh bin when an open bin achieves exact-fit with next item
        if next_item_size > 0 && next_item_size <= post_residual && post_residual == next_item_size && remaining > 16.0 {
            score += 45.0;
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
        if remaining < 32.0 {
            score += 0.6 * (32.0 - remaining);
        }
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        if remaining < 12.0 {
            score += 55.0;
        }
        let expected_future = remaining * (mean_residual / cap_f).max(0.15);
        if expected_future < 0.5 * cap_f && open_bins_count > 3 {
            score += 7.0 * (1.0 - expected_future / (0.5 * cap_f));
        }
        // GEN45: fragmentation-driven fresh-bin pull when next item is medium-large
        if open_bins_count > 10 && next_frac > 0.35 && remaining > 96.0 && next_item_size > post_residual {
            score -= 5.0;
        }
    } else {
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
            score += 5.0;
        }
        if fitting_bins_count > 3 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score += 0.05 * (post_f * post_f) / cap_f;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin generally.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if no open bin fits, or this is the only fitting bin, opening is fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // Large items prefer fresh bins (avoid fragmentation).
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        return score;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: small dead space classes are best.
    let cap = bin_capacity as f64;
    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Harmonic penalty: waste weighted by how much of capacity it strands.
        score += (cap / (cap - dead).max(1.0)) * 10.0;
    }

    // Modulo classes: residuals that are multiples of common item classes are reusable.
    let pr = post_residual as i64;
    if pr % 10 == 0 {
        score -= 8.0; // divisible into small item sizes
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; penalize leaving awkward residue.
            score += 5.0;
            if post_residual < next_item_size && post_residual > 0 {
                score += (post_residual as f64) * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Threshold on post_residual: very small residues are near-perfect fills.
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space below minimum item size
    } else if post_residual < 20 {
        score += 12.0; // near-dead space: only tiny items can use it
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: fully consumed bin
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 8.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer dense packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.5 * pressure * (1.0 - progress);

    // New-bin candidate: make it unattractive unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual - (post_residual as f64); // mean residual of others
        // Prefer new bin only when existing residuals are small (poor fits elsewhere).
        if fragmentation < 15.0 && fitting_bins_count > 0 {
            score -= 20.0; // everything is tight -> fresh bin is fine
        } else {
            score += 35.0; // keep using existing bins
        }
        // Early stream: opening bins is cheaper.
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post_residual exactly, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; leaving moderate residual is fine.
        score += 3.0;
    }

    // Mild preference for bins with below-average residual (keep large gaps alive).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual close to 0 or small dead space)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else {
        // penalize dead space quadratically
        score += (post_residual as f64) * (post_residual as f64) / 40.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.6;
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.3;
        }
    }

    // Compare post_residual against mean residual: avoid leaving this bin
    // far above the average (creates fragmented outliers)
    let drift = post_residual as f64 - mean_residual;
    if drift > 0.0 {
        score += drift * 0.15;
    } else {
        score += drift * 0.05; // slight reward for below-average residual
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // If lookahead suggests next item pairs well with a fresh bin, soften penalty
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let remaining = (total_items - step_index) as f64;
    let mut score = post_f;
    let horizon = (remaining / total_items.max(1) as f64).min(1.0);

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits in the leftover: reward tight two-item packing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 200.0 - (leftover_after_next as f64) * 1.5;
        // smooth decay reward: strongly prefers small remainders after the next item
        score -= 55.0 / (1.0 + leftover_after_next as f64 / 10.0);
        // chain lookahead: same item could fit again after the next one
        if leftover_after_next >= next_item_size {
            score -= 8.0;
            if leftover_after_next == 2 * next_item_size {
                score -= 12.0;
            }
            if leftover_after_next >= 3 * next_item_size {
                score -= 4.0;
                if remaining > 96.0 {
                    score -= 4.0;
                    let four = leftover_after_next - 3 * next_item_size;
                    if four >= next_item_size {
                        score -= 3.0;
                        if four == next_item_size {
                            score -= 5.0;
                        }
                    }
                }
            }
        }
        // exact fill after next item is highly desirable
        if leftover_after_next == 0 {
            score -= 140.0;
        } else if leftover_after_next <= 4 {
            score -= 30.0;
        } else if leftover_after_next <= 8 {
            score -= 18.0;
        }
        // dead-space: leftover after next is unusably small for next item
        if leftover_after_next > 0 && leftover_after_next < next_item_size && (leftover_after_next as f64) < mean_residual * 0.25 {
            score += 10.0;
        }
        // bonus when residual is a multiple of the next item (perfect tiling)
        if leftover_after_next % next_item_size.max(1) == 0 {
            score -= 9.0;
        }
        if post_residual % 25 == 0 {
            score -= 7.0;
        } else if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // pair-coverage coupling
        if remaining > 48.0 && leftover_after_next >= next_item_size {
            let two_post = leftover_after_next - next_item_size;
            if two_post >= item_size {
                score -= 3.5;
            }
            if two_post == 0 {
                score -= 12.0;
            } else if two_post <= 6 {
                score -= 8.0;
            }
        }
        // consumed-fraction bonus: next item nearly fills the residual
        let consumed_frac = next_item_size as f64 / post_f;
        if consumed_frac > 0.85 {
            score -= 10.0 * (consumed_frac - 0.85) * 10.0;
        }
        // two-item lookahead fill ratio
        let fill = (item_size + next_item_size) as f64 / post_f.max(1.0);
        if fill > 0.9 && fill <= 1.0 {
            score -= 6.0 * (fill - 0.9) * 10.0;
        }
        // residual-class shaping
        let class = (post_residual * 8) / bin_capacity;
        score -= 4.0 * class as f64 * horizon;
        // stronger reusable-remainder discount
        score -= 7.0 * ((leftover_after_next as f64) / (next_item_size as f64)).min(2.0) * horizon;
        // small clean remainders are excellent staging space
        if leftover_after_next <= 3 {
            score -= 18.0 * (4 - leftover_after_next) as f64;
        } else if leftover_after_next % 10 == 0 {
            score -= 12.0;
        }
        // curvature shaping: prefer post residuals near the next item size
        let curvature = 0.08 + 0.04 * (1.0 - horizon);
        score += curvature * ((leftover_after_next as f64) - (next_item_size as f64)).abs();
        // small-residual sweet spot: residuals of 8-11 fit many small items
        if post_residual >= 8 && post_residual <= 11 {
            score -= 10.0;
        }
        // residual in the 12-20 band is also highly reusable — mild bonus
        if post_residual >= 12 && post_residual <= 20 {
            score -= 6.0;
        }
        // chained reuse reward
        if post_residual >= 2 * next_item_size + item_size && remaining > 24.0 {
            score -= 12.0 * horizon;
        }
        // GEN45: two-step lookahead — reward residuals that can host next item twice
        if post_residual >= 2 * next_item_size && remaining > 32.0 {
            let two_slack = post_residual - 2 * next_item_size;
            if two_slack == 0 {
                score -= 10.0 * (0.5 + horizon);
            } else if two_slack <= 6 {
                score -= 4.5 * (0.5 + horizon);
            }
        }
        // GEN45: three-step lookahead for large residuals late in stream
        if post_residual >= 3 * next_item_size && remaining > 96.0 {
            score -= 5.0 * horizon;
        }
        // GEN45: sharpen zero-slack reward when post == next item exactly
        if leftover_after_next == 0 && remaining > 16.0 {
            score -= 16.0;
        }
    }
    // Next item will NOT fit: penalize dead space, worse when it's small.
    if next_item_size > post_residual {
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
        if post_residual > 0 && gap <= 6 {
            score += 6.0;
        }
        if post_residual > 0 {
            let wf = post_f / cap_f;
            score += 8.0 + 60.0 * wf * wf;
            if remaining > 64.0 && post_residual >= 8 {
                score += 0.4 * (gap as f64).min(20.0);
            }
            let dead_frac = gap as f64 / next_item_size as f64;
            score += 2.5 * dead_frac * horizon * (1.0 + wf);
            if post_residual >= 8 {
                score += 0.06 * post_f * (remaining / 256.0).min(1.0);
            }
            if remaining > 32.0 {
                let frag = (open_bins_count as f64 / 16.0).min(1.0);
                score += 1.3 * gap as f64 * frag * (remaining / 512.0).min(1.0);
            }
            if post_residual >= item_size && gap <= 6 {
                score += (7.0 - gap as f64) * 2.2 * (0.4 + horizon);
            }
            // GEN45: near-miss residuals are the main dead-space source — harder penalty
            if gap <= 10 {
                score += (10.5 - gap as f64) * 2.4 * (0.4 + horizon);
            }
        }
    }

    // Reward bins tighter than the mean residual (good fill), punish loose ones.
    score -= (mean_residual - post_f) * 0.5;

    // Reward tightness of the actual placement relative to bin residual.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Quadratic residual fraction: strong pull toward full bins.
    score += 32.0 * (post_f / cap_f) * (post_f / cap_f);

    // Last-chance bin: use it when the fit is tight.
    if fitting_bins_count == 1 {
        score -= 65.0 * (1.0 - post_f / cap_f);
    } else if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize leaving tiny unusable fragments (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 80.0;
    } else if post_residual < 12 {
        score += 20.0 * (12 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 1100.0;
    }

    // Progress term: keep flexibility early, prefer closing bins late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_f * 0.3;
    score += 0.25 * progress * post_f;

    // residual-reusability shaping with sharper cliff near exact reuse
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 6 {
            score -= 9.0 * (7.0 - slack as f64) * (0.5 + horizon);
        } else if slack < next_item_size {
            score += 3.1 * (slack as f64 / next_item_size as f64) * (0.5 + horizon);
        }
    }
    // prefer residuals matching common small-item sizes on long streams
    if next_item_size > 0 && post_residual > 0 && remaining > 64.0 && (post_residual % 10 == 0 || post_residual % 5 == 0) {
        score -= 3.5;
    }

    // NEW-BIN CANDIDATE handling
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
        if item_size as f64 > 0.85 * cap_f {
            score -= 40.0;
        }
        if open_bins_count > 4 && mean_residual > 0.6 * cap_f {
            score -= 12.0;
        }
        if fitting_bins_count > 2 && item_size as f64 <= mean_residual {
            score += 18.0;
        }
        if fitting_bins_count >= 1 && item_size as f64 <= mean_residual * 0.8 {
            score += 22.0;
        }
        if open_bins_count > 6 && item_size as f64 <= 0.5 * cap_f && fitting_bins_count >= 2 {
            score += 14.0;
        }
        // fresh-bin lookahead
        if next_item_size > post_residual {
            if remaining > 48.0 {
                score -= 30.0 * (1.0 - post_f / cap_f);
            }
            if post_f < 0.06 * cap_f && remaining > 128.0 {
                score -= 12.0;
            }
            if post_f <= 4.0 && remaining > 24.0 {
                score -= 18.0;
            }
            if post_f <= 0.10 * cap_f && remaining > 220.0 {
                score -= 12.0;
            }
            if remaining > 96.0 && (next_item_size as f64) > 3.0 * post_f {
                score -= 10.0;
            }
        }
        if next_item_size > post_residual && fitting_bins_count == 0 && remaining > 64.0 {
            score -= 20.0;
        }
        let next_frac = next_item_size as f64 / cap_f;
        if next_frac > 0.5 && remaining > 64.0 {
            score -= 14.0 * (next_frac - 0.5);
        }
        if next_frac > 0.5 && fitting_bins_count <= 2 && remaining > 32.0 {
            score -= 10.0 * next_frac;
        }
        if next_frac < 0.25 && open_bins_count > 4 && remaining > 64.0 {
            score += 9.0;
        }
        if open_bins_count > 8 && remaining > 128.0 && next_frac < 0.45 {
            score += 5.0 + 3.0 * (0.45 - next_frac);
        }
        if open_bins_count > 6 && remaining > 200.0 && next_frac > 0.6 {
            score -= 8.0;
        }
        // very large next item on a long stream — fresh bin strongly preferred
        if next_frac > 0.85 && remaining > 96.0 {
            score -= 6.0;
        }
        // GEN45: fresh-bin pull when fragmentation is high and next item medium
        if open_bins_count > 10 && next_frac > 0.35 && remaining > 96.0 && next_item_size > post_residual {
            score -= 5.0;
        }
        let load = (bin_capacity - post_residual) as f64 / cap_f;
        if load < 0.55 && next_item_size > post_residual {
            score += 40.0;
        } else {
            score += 6.0 * load;
        }
        if remaining < 32.0 {
            score += 0.6 * (32.0 - remaining);
        }
        if remaining < 48.0 && open_bins_count > 2 {
            score += 0.25 * (48.0 - remaining);
        }
        if remaining < 12.0 {
            score += 55.0;
        }
        let expected_future = remaining * (mean_residual / cap_f).max(0.15);
        if expected_future < 0.5 * cap_f && open_bins_count > 3 {
            score += 7.0 * (1.0 - expected_future / (0.5 * cap_f));
        }
        // GEN45: discourage opening fresh bin when an open bin achieves exact-fit with next item
        if next_item_size > 0 && post_residual == next_item_size && remaining > 16.0 {
            score += 45.0;
        }
    } else {
        if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size > 14 && remaining < 64.0 {
            score += 5.0;
        }
        if fitting_bins_count > 3 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        if fitting_bins_count <= 2 && post_residual > 0 {
            score += 0.05 * (post_f * post_f) / cap_f;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a residual the next item cannot use (dead space risk).
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be more willing to keep bins flexible;
    // late in the stream, prioritize closing out bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual is high, favor bins near the mean
    // (balanced packing); if low, favor the tightest bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless current bin is a bad fit
    // or nothing else fits. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let waste = item_size as f64 / bin_capacity as f64;
        // Opening a bin for a small item wastes capacity; discourage, but allow
        // when other bins are scarce or mean residual is tiny (all bins nearly full).
        score += 20.0 * (1.0 - waste);
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a bin anyway
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Pairing potential makes a fresh bin more attractive.
            score -= 5.0;
        }
    }

    // Perfect fit jackpot.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Polynomial interaction: waste penalized more as stream progresses
    let coupling = pr_norm * (1.0 + 2.0 * progress + 3.0 * p2 + 1.5 * p3);
    score += 4.0 * coupling;

    // Tight fits rewarded, scaled non-linearly by progress
    let tightness = 1.0 - pr_norm;
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let drift = pr_norm - mean_residual / bin_capacity as f64;
    score += 3.0 * drift * drift;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Lookahead: favor bins leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = (pr - nx) / bin_capacity as f64;
        let kernel = (-4.0 * room * room).exp();
        score -= 2.5 * kernel * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins, growing with progress
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small dead space classes are good.
    let post_class = post_residual / 10; // integer division thresholds (0..=9)
    score -= (10 - post_class as f64) * 2.0;

    // Perfect / near-perfect fit rewards
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize "awkward" dead space classes that few items can fill:
    // residuals in (10, 20) and (30, 40) are hard to reuse (items >= 10).
    if post_residual > 10 && post_residual < 20 {
        score += 15.0;
    }
    if post_residual > 30 && post_residual < 40 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // harmonic class of the residual after the chain placement
            if next_post == 0 {
                score -= 30.0;
            } else if next_post <= 10 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here after placement; mild penalty scaled
            // by how much the next item overshoots.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // but should win when no open bin offers a decent fit. Give the empty
    // bin a baseline so it competes fairly.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // Early in the stream, opening bins is cheap and keeps options open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // If many open bins but none fit well, new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Prefer tighter bins overall: compare residual to the mean residual.
    let tightness = (bin_residual as f64 - mean_residual).max(0.0);
    score += tightness * 0.2;

    // Mild penalty for bin sprawl: encourage consolidation when many bins open.
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.5;
    }

    // Modulo-based micro-tuning on post_residual classes (harmonic buckets).
    match post_residual % 10 {
        0 => score -= 6.0,          // clean decade residual, easy to reuse
        1 | 2 | 3 => score += 3.0,  // sliver residuals, nearly dead space
        8 | 9 => score -= 2.0,      // almost a decade, likely fillable
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}
